const lessons = [
{title:"Einführung & Setup",short:"Einführung & Setup",desc:"Lerne, was JavaScript macht, und führe dein erstes Programm aus.",goals:["Du weißt, wofür JavaScript verwendet wird","Du kennst HTML, CSS und JavaScript","Du kannst console.log() verwenden"],section:"1.1 Was ist JavaScript?",body:"JavaScript macht Webseiten interaktiv und kann auch Daten verarbeiten oder Anwendungen antreiben. HTML beschreibt die Struktur, CSS das Aussehen und JavaScript das Verhalten einer Webseite.",example:'console.log("Hallo Welt!");',expected:"Hallo Welt!",task:"Ändere den Code so, dass die Konsole deinen eigenen Begrüßungstext ausgibt.",quiz:{q:"Welche Aufgabe übernimmt JavaScript typischerweise auf einer Webseite?",opts:["Die Struktur der Seite festlegen","Das Verhalten und die Interaktivität steuern","Nur Farben und Abstände festlegen"],correct:1,explain:"HTML liefert die Struktur, CSS das Aussehen und JavaScript das Verhalten."}},
{title:"Variablen",short:"Variablen",desc:"Speichere Werte in benannten Variablen und lerne let und const kennen.",goals:["Du kannst Variablen deklarieren","Du unterscheidest let und const","Du kannst Werte ausgeben"],section:"2.1 Werte speichern",body:"Eine Variable ist ein benannter Verweis auf einen Wert. Verwende const, wenn die Variable nicht neu zugewiesen werden soll, und let, wenn du sie später neu zuweisen musst.",example:'let punkte = 10;\npunkte = 15;\nconst name = "Alex";\nconsole.log(punkte);\nconsole.log(name);',expected:"15\nAlex",task:"Erstelle eine Variable stadt und gib ihren Wert aus.",quiz:{q:"Welches Schlüsselwort eignet sich, wenn du einer Variablen später einen neuen Wert zuweisen möchtest?",opts:["const","let","return"],correct:1,explain:"Mit let kann die Variable neu zugewiesen werden."}},
{title:"Datentypen",short:"Datentypen",desc:"Unterscheide Text, Zahlen, Wahrheitswerte und fehlende Werte.",goals:["Du erkennst Strings und Numbers","Du kennst true und false","Du kannst typeof einsetzen"],section:"3.1 Grundlegende Typen",body:"Strings sind Texte, Numbers sind Zahlen und Booleans sind true oder false. undefined bedeutet oft, dass noch kein Wert zugewiesen wurde. null steht für einen bewusst leeren Wert.",example:'const name = "Mira";\nconst alter = 28;\nconst aktiv = true;\nconsole.log(typeof name);\nconsole.log(typeof alter);\nconsole.log(typeof aktiv);',expected:"string\nnumber\nboolean",task:"Gib mit typeof den Datentyp von 42 aus.",quiz:{q:"Welcher Datentyp ist der Wert true?",opts:["String","Boolean","Number"],correct:1,explain:"true und false sind Boolean-Werte."}},
{title:"Operatoren",short:"Operatoren",desc:"Rechne mit Zahlen und vergleiche Werte.",goals:["Du kennst Rechenoperatoren","Du kannst Werte vergleichen","Du verwendest ==="],section:"4.1 Rechnen und vergleichen",body:"Mit +, -, * und / rechnest du. Vergleichsoperatoren wie ===, !==, > und <= liefern einen Boolean. === vergleicht Wert und Datentyp ohne automatische Typumwandlung.",example:'const a = 10;\nconst b = 3;\nconsole.log(a + b);\nconsole.log(a % b);\nconsole.log(5 === "5");',expected:"13\n1\nfalse",task:"Berechne 7 mal 8 und gib das Ergebnis aus.",quiz:{q:"Was ergibt 5 === \"5\"?",opts:["true","false","25"],correct:1,explain:"Die Zahl 5 und der Text \"5\" haben unterschiedliche Datentypen."}},
{title:"Bedingungen",short:"Bedingungen",desc:"Lass dein Programm anhand von Bedingungen Entscheidungen treffen.",goals:["Du verwendest if und else","Du kannst Bedingungen kombinieren","Du verstehst Vergleichsergebnisse"],section:"5.1 Entscheidungen",body:"Mit if wird ein Codeblock ausgeführt, wenn eine Bedingung wahr ist. else beschreibt den Alternativfall. Mit else if kannst du weitere Fälle prüfen.",example:'const alter = 17;\nif (alter >= 18) {\n  console.log("Volljährig");\n} else {\n  console.log("Noch nicht volljährig");\n}',expected:"Noch nicht volljährig",task:"Passe das Alter an und teste beide Zweige.",quiz:{q:"Welcher Block läuft, wenn die if-Bedingung falsch ist?",opts:["else","const","console"],correct:0,explain:"else enthält den Alternativfall, wenn die if-Bedingung nicht zutrifft."}},
{title:"Schleifen",short:"Schleifen",desc:"Wiederhole Anweisungen effizient mit for und while.",goals:["Du liest eine for-Schleife","Du kennst i++","Du vermeidest Endlosschleifen"],section:"6.1 Code wiederholen",body:"Eine for-Schleife enthält einen Startwert, eine Bedingung und eine Veränderung. Die Schleife endet, wenn die Bedingung falsch wird.",example:'for (let i = 1; i <= 5; i++) {\n  console.log(i);\n}',expected:"1\n2\n3\n4\n5",task:"Ändere die Schleife, sodass sie die Zahlen von 1 bis 10 ausgibt.",quiz:{q:"Was macht i++?",opts:["Erhöht i um eins","Setzt i auf null","Beendet das Programm"],correct:0,explain:"i++ erhöht den aktuellen Wert von i um eins."}},
{title:"Funktionen",short:"Funktionen",desc:"Bündle Code in wiederverwendbare Funktionen.",goals:["Du definierst Funktionen","Du verwendest Parameter","Du verstehst return"],section:"7.1 Code wiederverwenden",body:"Funktionen bündeln Anweisungen. Parameter nehmen Eingaben entgegen. return gibt ein Ergebnis an den Aufrufer zurück.",example:'function addiere(a, b) {\n  return a + b;\n}\nconsole.log(addiere(4, 6));',expected:"10",task:"Schreibe eine Funktion multipliziere(a, b), die das Produkt zurückgibt.",quiz:{q:"Wofür wird return verwendet?",opts:["Um ein Ergebnis zurückzugeben","Um eine Variable zu deklarieren","Um eine Schleife zu starten"],correct:0,explain:"return beendet die Funktion und liefert optional einen Wert zurück."}},
{title:"Arrays",short:"Arrays",desc:"Speichere geordnete Listen von Werten.",goals:["Du greifst über Indizes zu","Du kennst push()","Du durchläufst ein Array"],section:"8.1 Listen von Werten",body:"Arrays speichern mehrere Werte in einer geordneten Liste. Der erste Index ist 0. push() fügt ein Element am Ende hinzu.",example:'const fruechte = ["Apfel", "Banane"];\nfruechte.push("Orange");\nfor (const frucht of fruechte) {\n  console.log(frucht);\n}',expected:"Apfel\nBanane\nOrange",task:"Erstelle ein Array mit drei Lieblingsspielen und gib jedes einzeln aus.",quiz:{q:"Welchen Index hat das erste Array-Element?",opts:["0","1","-1"],correct:0,explain:"JavaScript-Arrays sind nullbasiert: Das erste Element hat Index 0."}},
{title:"Objekte",short:"Objekte",desc:"Organisiere zusammengehörige Daten in Eigenschaften und Werten.",goals:["Du erstellst Objekte","Du greifst auf Eigenschaften zu","Du veränderst Eigenschaften"],section:"9.1 Daten gruppieren",body:"Objekte speichern Daten als Eigenschaften mit Werten. Auf Eigenschaften greifst du beispielsweise mit person.name zu. Ein const-Objekt kann intern verändert werden, aber die Variable nicht neu zugewiesen werden.",example:'const person = {\n  name: "Mira",\n  alter: 28\n};\nperson.alter = 29;\nconsole.log(person.name);\nconsole.log(person.alter);',expected:"Mira\n29",task:"Erstelle ein Objekt auto mit den Eigenschaften marke und baujahr.",quiz:{q:"Wie liest du die Eigenschaft name aus person aus?",opts:["person->name","person.name","person(name)"],correct:1,explain:"Die Punktnotation person.name liest die Eigenschaft name."}},
{title:"DOM & HTML",short:"DOM & HTML",desc:"Finde HTML-Elemente und verändere ihren Inhalt.",goals:["Du verstehst das DOM","Du findest Elemente per ID","Du änderst textContent"],section:"10.1 Die Webseite verändern",body:"Das Document Object Model (DOM) bildet die HTML-Struktur als Objekte ab. JavaScript kann diese Elemente finden und ändern. In dieser Lektion nutzt du ein simuliertes DOM-Beispiel in der Konsole.",example:'const ueberschrift = {\n  textContent: "Alter Text"\n};\nueberschrift.textContent = "Neuer Text";\nconsole.log(ueberschrift.textContent);',expected:"Neuer Text",task:"Ändere den neuen Text in eine eigene Überschrift.",quiz:{q:"Wofür steht textContent?",opts:["Für den Textinhalt eines Elements","Für die Hintergrundfarbe","Für eine Datenbank"],correct:0,explain:"textContent liest oder setzt den Textinhalt eines DOM-Elements."}},
{title:"Ereignisse",short:"Ereignisse",desc:"Reagiere auf Klicks und andere Benutzeraktionen.",goals:["Du verstehst Ereignis-Listener","Du kennst click","Du verbindest Aktionen mit Funktionen"],section:"11.1 Auf Benutzer reagieren",body:"Ein Ereignis-Listener registriert eine Funktion, die bei einem Ereignis ausgeführt wird. Häufige Ereignisse sind click, input und submit.",example:'function beiKlick() {\n  console.log("Button angeklickt!");\n}\nbeiKlick();',expected:"Button angeklickt!",task:"Ändere die Nachricht, die beim Funktionsaufruf ausgegeben wird.",quiz:{q:"Was bewirkt addEventListener(\"click\", handler)?",opts:["Registriert eine Funktion für Klicks","Löscht den Button","Startet eine Schleife"],correct:0,explain:"Der Listener führt den Handler aus, wenn das Element angeklickt wird."}},
{title:"Projekt: Zähler",short:"Projekt: Zähler",desc:"Kombiniere Variablen, Funktionen und Ereignisse in einem kleinen Projekt.",goals:["Du veränderst einen Zählerwert","Du aktualisierst die Anzeige","Du setzt den Wert zurück"],section:"12.1 Zählerlogik",body:"Ein Zähler speichert einen veränderlichen Zahlenwert. Bei jedem Schritt änderst du die Zahl und aktualisierst die Anzeige. Hier übst du zuerst die Logik in der Konsole.",example:'let zahl = 0;\nzahl++;\nzahl++;\nconsole.log(zahl);\nzahl = 0;\nconsole.log(zahl);',expected:"2\n0",task:"Ergänze eine weitere Erhöhung und beobachte das Ergebnis.",quiz:{q:"Welche Anweisung setzt zahl auf null als Zahlwert?",opts:["zahl === 0","zahl = 0","const zahl++"],correct:1,explain:"Mit zahl = 0 weist du der Variablen den Zahlenwert 0 zu."}},
{title:"Nächste Schritte",short:"Nächste Schritte",desc:"Lerne, wie du deine Grundlagen festigst und weiterführende Themen angehst.",goals:["Du kennst sinnvolle nächste Themen","Du kannst deine Grundlagen wiederholen","Du planst ein eigenes Mini-Projekt"],section:"13.1 Weiterlernen",body:"Als Nächstes kannst du Array-Methoden, Fehlerbehandlung, Module, JSON, Promises, async/await und fetch() lernen. Baue kleine Projekte und lies Fehlermeldungen sorgfältig.",example:'const zahlen = [1, 2, 3, 4];\nconst verdoppelt = zahlen.map(n => n * 2);\nconsole.log(verdoppelt.join(", "));',expected:"2, 4, 6, 8",task:"Ändere die map-Funktion so, dass jede Zahl verdreifacht wird.",quiz:{q:"Wofür wird fetch() häufig verwendet?",opts:["Um HTTP-Anfragen zu stellen","Um CSS zu schreiben","Um eine Schleife zu beenden"],correct:0,explain:"fetch() wird häufig genutzt, um Daten über HTTP von einer API abzurufen."}}
];
const explanations=["<p>JavaScript ist eine Programmiersprache. Damit sagst du einem Computer, welche Schritte er ausführen soll. Auf Webseiten kann JavaScript auf Klicks reagieren, Zahlen berechnen, Formulare prüfen und Inhalte verändern. Es wird aber auch für Server und andere Anwendungen eingesetzt.</p><p>Eine Webseite nutzt häufig drei Bausteine: <b>HTML</b> beschreibt die Struktur (zum Beispiel Überschriften und Schaltflächen), <b>CSS</b> bestimmt das Aussehen (Farben und Abstände) und <b>JavaScript</b> fügt Verhalten hinzu. In dieser Lernplattform schreibst du JavaScript und siehst die Ausgabe direkt neben dem Editor.</p><h2>Dein erster Befehl: console.log()</h2><p><span class=\"code-inline\">console.log()</span> schreibt Informationen in die Konsole. Die runden Klammern enthalten, was ausgegeben werden soll. Text wird in Anführungszeichen geschrieben. Das Semikolon beendet die Anweisung sichtbar und ist für den Anfang eine gute Gewohnheit.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe <span class=\"code-inline\">console.log(\"Hallo Welt!\");</span> in den leeren Editor und klicke auf „Code ausführen“. Rechts sollte der Text Hallo Welt! erscheinen. Ändere den Text in deinen eigenen Begrüßungssatz und führe den Code erneut aus.</div>", "<p>Eine Variable ist ein Name, unter dem du einen Wert speichern kannst. Stell dir ein beschriftetes Fach vor: Der Name hilft dir, den gespeicherten Wert später wiederzuverwenden. Variablen sind praktisch für Namen, Punktestände, Preise oder Ergebnisse von Berechnungen.</p><h2>let und const</h2><p><span class=\"code-inline\">let</span> verwendest du, wenn du einer Variablen später einen anderen Wert zuweisen möchtest. <span class=\"code-inline\">const</span> verwendest du, wenn der Variablenname dauerhaft auf denselben Wert zeigen soll. Als Faustregel: Nutze const, wenn du den Wert nicht neu zuweisen musst, und let, wenn du ihn ändern willst.</p><p>Das Zeichen <span class=\"code-inline\">=</span> weist einen Wert zu. Es bedeutet nicht „ist gleich?“. JavaScript unterscheidet außerdem Groß- und Kleinschreibung: <span class=\"code-inline\">punkte</span> und <span class=\"code-inline\">Punkte</span> sind unterschiedliche Namen.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe <span class=\"code-inline\">let punkte = 10;</span>, dann <span class=\"code-inline\">punkte = 15;</span> und anschließend <span class=\"code-inline\">console.log(punkte);</span>. Führe den Code aus. Ändere die 15 und beobachte, wie sich die Ausgabe verändert.</div>", "<p>Ein Datentyp beschreibt, um welche Art von Wert es sich handelt. Das ist wichtig, weil JavaScript mit Text anders umgeht als mit Zahlen oder Wahrheitswerten.</p><p><b>String</b> ist Text, zum Beispiel <span class=\"code-inline\">\"Hallo\"</span>. <b>Number</b> ist eine Zahl, zum Beispiel <span class=\"code-inline\">42</span> oder <span class=\"code-inline\">3.5</span>. <b>Boolean</b> ist ein Wahrheitswert: <span class=\"code-inline\">true</span> oder <span class=\"code-inline\">false</span>. <span class=\"code-inline\">undefined</span> bedeutet häufig, dass noch kein Wert gesetzt wurde.</p><p>Mit <span class=\"code-inline\">typeof</span> fragst du JavaScript nach dem Typ eines Wertes. Das hilft besonders, wenn du nicht sicher bist, ob du mit einer Zahl oder mit Text arbeitest.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe <span class=\"code-inline\">console.log(typeof 42);</span>. Ergänze darunter <span class=\"code-inline\">console.log(typeof \"42\");</span>. Führe beides aus und vergleiche die Ergebnisse: Die erste 42 ist eine Zahl, die zweite ein Text.</div>", "<p>Operatoren verarbeiten Werte. Rechenoperatoren sind <span class=\"code-inline\">+</span> (addieren), <span class=\"code-inline\">-</span> (subtrahieren), <span class=\"code-inline\">*</span> (multiplizieren) und <span class=\"code-inline\">/</span> (dividieren). Der Operator <span class=\"code-inline\">%</span> gibt den Rest einer Division zurück.</p><p>Vergleichsoperatoren prüfen eine Aussage und liefern <span class=\"code-inline\">true</span> oder <span class=\"code-inline\">false</span>. Besonders wichtig ist <span class=\"code-inline\">===</span>: Er vergleicht sowohl den Wert als auch den Datentyp. Deshalb ist die Zahl 5 nicht strikt gleich dem Text \"5\". Für den Anfang solltest du meistens === statt == verwenden.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Gib <span class=\"code-inline\">console.log(7 * 8);</span> aus. Ergänze danach <span class=\"code-inline\">console.log(5 === \"5\");</span>. Erkläre dir selbst, warum die zweite Ausgabe false ist.</div>", "<p>Mit einer Bedingung kann dein Programm entscheiden, welche Anweisungen ausgeführt werden. <span class=\"code-inline\">if</span> prüft eine Aussage. Ist sie wahr, läuft der Code in den geschweiften Klammern. Ist sie falsch, kann der <span class=\"code-inline\">else</span>-Block ausgeführt werden. Mit <span class=\"code-inline\">else if</span> lassen sich weitere Fälle prüfen.</p><p>Eine Bedingung kann zum Beispiel prüfen, ob eine Zahl größer oder gleich 18 ist. Die runden Klammern enthalten die Frage, die geschweiften Klammern den Code für diesen Fall. Achte auf beide Arten von Klammern.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Lege <span class=\"code-inline\">const alter = 17;</span> an. Schreibe eine if/else-Abfrage, die „Volljährig“ ab 18 ausgibt und sonst „Noch nicht volljährig“. Ändere danach 17 in 18 und führe den Code erneut aus.</div>", "<p>Eine Schleife wiederholt Code. Wenn du zehn Zahlen ausgeben möchtest, musst du also nicht zehn einzelne console.log-Zeilen schreiben. Eine Schleife erledigt das mit wenigen Zeilen.</p><p>Bei einer <span class=\"code-inline\">for</span>-Schleife gibt es drei Bestandteile: einen Startwert, eine Bedingung und eine Veränderung nach jedem Durchlauf. Bei <span class=\"code-inline\">for (let i = 1; i <= 5; i++)</span> startet i bei 1, läuft solange i höchstens 5 ist und wird nach jedem Durchlauf um eins erhöht. Wenn die Bedingung falsch wird, endet die Schleife.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe eine for-Schleife, die die Zahlen von 1 bis 10 mit console.log(i) ausgibt. Ändere die Grenze auf 3 und dann auf 20. Achte darauf, dass die Schleife irgendwann endet.</div>", "<p>Eine Funktion bündelt Anweisungen unter einem Namen, damit du sie mehrfach verwenden kannst. Das macht Programme übersichtlicher und vermeidet doppelten Code. Du definierst eine Funktion und rufst sie später mit ihrem Namen und runden Klammern auf.</p><p>Werte, die eine Funktion benötigt, werden als <b>Parameter</b> angegeben. <span class=\"code-inline\">return</span> gibt ein Ergebnis an die aufrufende Stelle zurück. Das ist etwas anderes als console.log: log zeigt einen Wert an, return liefert einen Wert, mit dem dein Programm weiterarbeiten kann.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe <span class=\"code-inline\">function addiere(a, b) { return a + b; }</span>. Gib danach <span class=\"code-inline\">console.log(addiere(4, 6));</span> aus. Ändere die beiden Zahlen und teste die Funktion erneut.</div>", "<p>Ein Array ist eine geordnete Liste. Es eignet sich, wenn mehrere Werte zusammengehören, zum Beispiel Namen, Aufgaben oder Punktestände. Ein Array steht in eckigen Klammern; die einzelnen Werte werden mit Kommas getrennt.</p><p>Der Zugriff erfolgt über einen Index. JavaScript beginnt beim Zählen mit 0: Das erste Element hat Index 0, das zweite Index 1. Mit <span class=\"code-inline\">push()</span> hängst du ein Element ans Ende an. Mit einer <span class=\"code-inline\">for...of</span>-Schleife kannst du alle Elemente nacheinander verarbeiten.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Erstelle <span class=\"code-inline\">const spiele = [\"Schach\", \"Minecraft\", \"Tetris\"];</span>. Gib <span class=\"code-inline\">spiele[0]</span> aus. Füge dann <span class=\"code-inline\">spiele.push(\"Mario Kart\");</span> hinzu und gib das gesamte Array aus.</div>", "<p>Ein Objekt gruppiert Informationen als Eigenschaften. Ein Personenobjekt könnte zum Beispiel name, alter und stadt enthalten. So bleiben zusammengehörige Daten an einem Ort und haben verständliche Namen.</p><p>Ein Objekt steht in geschweiften Klammern. Jede Eigenschaft besteht aus einem Namen, einem Doppelpunkt und einem Wert. Mit der Punktnotation <span class=\"code-inline\">person.name</span> liest du eine Eigenschaft. Ein Objekt, das mit const angelegt wurde, kann intern verändert werden; nur die Variable selbst darf nicht auf ein ganz anderes Objekt neu zugewiesen werden.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Erstelle ein Objekt auto mit den Eigenschaften marke und baujahr. Gib auto.marke aus. Ändere danach auto.baujahr und gib den neuen Wert aus.</div>", "<p>Der DOM (Document Object Model) ist die strukturierte Darstellung einer HTML-Seite, mit der JavaScript arbeiten kann. Du kannst HTML-Elemente auswählen, Text ändern, CSS-Klassen hinzufügen oder neue Elemente erstellen.</p><p>In einer echten Webseite könntest du mit <span class=\"code-inline\">document.querySelector(\"h1\")</span> eine Überschrift finden. Mit <span class=\"code-inline\">textContent</span> liest oder änderst du ihren Text. Dieser Lerneditor zeigt keine separate Beispiel-Webseite, deshalb üben wir die gleiche Eigenschaft an einem kleinen JavaScript-Objekt. So verstehst du zunächst die Zuweisung, bevor du sie an echten HTML-Elementen verwendest.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Erstelle <span class=\"code-inline\">const ueberschrift = { textContent: \"Alter Text\" };</span>. Setze danach <span class=\"code-inline\">ueberschrift.textContent = \"Meine Überschrift\";</span> und gib die Eigenschaft aus.</div>", "<p>Ein Ereignis ist etwas, das in einer Anwendung passiert: Ein Nutzer klickt auf eine Schaltfläche, tippt in ein Eingabefeld oder sendet ein Formular ab. JavaScript kann auf solche Ereignisse reagieren.</p><p>In einer echten Webseite registriert <span class=\"code-inline\">addEventListener(\"click\", handler)</span> eine Funktion, die beim Klick ausgeführt werden soll. Da der Editor selbst keine zusätzliche Beispiel-Webseite enthält, übst du hier die Funktion, die später als Ereignis-Handler dient. Der Funktionsaufruf simuliert, dass der Klick stattgefunden hat.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Definiere <span class=\"code-inline\">function beiKlick() { console.log(\"Button angeklickt!\"); }</span>. Rufe danach <span class=\"code-inline\">beiKlick();</span> auf und ändere die Meldung.</div>", "<p>In diesem Mini-Projekt kombinierst du mehrere Grundlagen. Eine Variable speichert den aktuellen Zählerstand. Mit <span class=\"code-inline\">++</span> erhöhst du die Zahl um eins. Mit <span class=\"code-inline\">zahl = 0</span> setzt du sie zurück. In einer echten Webseite würdest du nach jeder Änderung zusätzlich die sichtbare Anzeige aktualisieren.</p><p>Wichtig ist, dass du die Schritte in der richtigen Reihenfolge ausführst. Erst legst du den Startwert fest, dann änderst du ihn und zuletzt gibst du ihn aus. Du kannst die Logik schrittweise erweitern, bevor du daraus eine interaktive Webseite machst.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Schreibe <span class=\"code-inline\">let zahl = 0;</span>, erhöhe die Zahl dreimal mit <span class=\"code-inline\">zahl++;</span> und gib sie aus. Setze sie dann auf 0 und gib sie noch einmal aus.</div>", "<p>Du hast die wichtigsten Bausteine kennengelernt: Variablen, Datentypen, Operatoren, Bedingungen, Schleifen, Funktionen, Arrays und Objekte. Als Nächstes geht es darum, diese Bausteine in kleinen eigenen Projekten zu kombinieren und dabei selbst Lösungen zu finden.</p><p>Weitere sinnvolle Themen sind Array-Methoden wie <span class=\"code-inline\">map()</span> und <span class=\"code-inline\">filter()</span>, Fehlerbehandlung mit <span class=\"code-inline\">try...catch</span>, Module, JSON und asynchrone Programmierung mit Promises sowie <span class=\"code-inline\">async/await</span>. Mit <span class=\"code-inline\">fetch()</span> kannst du später Daten von Web-APIs abrufen.</p><div class=\"guide-step\"><strong>Probiere es jetzt aus</strong>Erstelle das Array <span class=\"code-inline\">[1, 2, 3, 4]</span>. Verwende <span class=\"code-inline\">map()</span>, um jede Zahl zu verdreifachen, und gib das neue Array aus. Versuche anschließend in eigenen Worten zu erklären, was die Funktion innerhalb von map macht.</div>"];
const advancedLessons = [{"title":"Typumwandlung & Wahrheitswerte","short":"Typumwandlung","desc":"Verstehe automatische und explizite Typumwandlung sowie Truthy und Falsy.","goals":["Du erkennst implizite Umwandlung","Du kannst Number() einsetzen","Du verstehst Truthy und Falsy"],"section":"Typen bewusst umwandeln","body":"JavaScript kann Werte automatisch umwandeln. Das kann praktisch sein, aber auch unerwartete Ergebnisse erzeugen. Nutze Number(), String() oder Boolean(), wenn du die Umwandlung ausdrücklich machen willst. Werte wie 0, \"\", null, undefined und NaN sind falsy; viele andere Werte sind truthy.","example":"const eingabe = \"42\";\nconst zahl = Number(eingabe);\nconsole.log(zahl + 8);\nconsole.log(Boolean(\"Hallo\"));\nconsole.log(Boolean(\"\"));","expected":"50\ntrue\nfalse","task":"Wandle den Text \"125\" in eine Zahl um und addiere 25.","quiz":{"q":"Was ergibt Boolean(\"\")?","opts":["true","false","undefined"],"correct":1,"explain":"Der leere String ist falsy, deshalb ergibt Boolean(\"\") den Wert false."},"explanation":"<p>JavaScript kann Werte automatisch umwandeln. Das kann praktisch sein, aber auch unerwartete Ergebnisse erzeugen. Nutze Number(), String() oder Boolean(), wenn du die Umwandlung ausdrücklich machen willst. Werte wie 0, \"\", null, undefined und NaN sind falsy; viele andere Werte sind truthy.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const eingabe = &quot;42&quot;;\nconst zahl = Number(eingabe);\nconsole.log(zahl + 8);\nconsole.log(Boolean(&quot;Hallo&quot;));\nconsole.log(Boolean(&quot;&quot;));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">50\ntrue\nfalse</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Wandle den Text \"125\" in eine Zahl um und addiere 25.</div>"},{"title":"Logische Operatoren & switch","short":"Logik & switch","desc":"Kombiniere Bedingungen und wähle zwischen mehreren Fällen.","goals":["Du nutzt &&, || und !","Du kannst Bedingungen kombinieren","Du kennst switch"],"section":"Mehrere Fälle prüfen","body":"Mit && müssen beide Bedingungen wahr sein. Mit || reicht eine wahre Bedingung. ! kehrt einen Wahrheitswert um. switch ist praktisch, wenn du einen Wert mit mehreren konkreten Fällen vergleichen willst.","example":"const alter = 22;\nconst hatTicket = true;\nconsole.log(alter >= 18 && hatTicket);\nconst tag = \"samstag\";\nswitch (tag) {\n  case \"samstag\": console.log(\"Wochenende\"); break;\n  case \"sonntag\": console.log(\"Wochenende\"); break;\n  default: console.log(\"Werktag\");\n}","expected":"true\nWochenende","task":"Ergänze eine Prüfung, die nur true ergibt, wenn eine Zahl mindestens 10 und höchstens 20 ist.","quiz":{"q":"Welcher Operator bedeutet „beide Bedingungen müssen stimmen“?","opts":["||","&&","!"],"correct":1,"explain":"&& ist der logische UND-Operator."},"explanation":"<p>Mit && müssen beide Bedingungen wahr sein. Mit || reicht eine wahre Bedingung. ! kehrt einen Wahrheitswert um. switch ist praktisch, wenn du einen Wert mit mehreren konkreten Fällen vergleichen willst.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const alter = 22;\nconst hatTicket = true;\nconsole.log(alter &gt;= 18 &amp;&amp; hatTicket);\nconst tag = &quot;samstag&quot;;\nswitch (tag) {\n  case &quot;samstag&quot;: console.log(&quot;Wochenende&quot;); break;\n  case &quot;sonntag&quot;: console.log(&quot;Wochenende&quot;); break;\n  default: console.log(&quot;Werktag&quot;);\n}</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">true\nWochenende</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Ergänze eine Prüfung, die nur true ergibt, wenn eine Zahl mindestens 10 und höchstens 20 ist.</div>"},{"title":"Weitere Schleifen","short":"for...of & while","desc":"Verarbeite Listen und wiederhole Code mit unterschiedlichen Schleifen.","goals":["Du nutzt for...of","Du verstehst while","Du kannst break und continue einordnen"],"section":"Die passende Schleife wählen","body":"for...of verarbeitet die Werte einer iterierbaren Sammlung direkt. while wiederholt Code, solange eine Bedingung wahr ist. break beendet eine Schleife vorzeitig; continue überspringt den Rest des aktuellen Durchlaufs. Achte darauf, dass while-Schleifen ihre Bedingung irgendwann ändern.","example":"const namen = [\"Ava\", \"Ben\", \"Chris\"];\nfor (const name of namen) {\n  console.log(name);\n}\nlet zahl = 1;\nwhile (zahl <= 3) {\n  console.log(zahl);\n  zahl++;\n}","expected":"Ava\nBen\nChris\n1\n2\n3","task":"Schreibe eine while-Schleife, die von 5 bis 1 herunterzählt.","quiz":{"q":"Was macht break?","opts":["Überspringt nur einen Durchlauf","Beendet die Schleife","Startet die Schleife neu"],"correct":1,"explain":"break beendet die aktuelle Schleife."},"explanation":"<p>for...of verarbeitet die Werte einer iterierbaren Sammlung direkt. while wiederholt Code, solange eine Bedingung wahr ist. break beendet eine Schleife vorzeitig; continue überspringt den Rest des aktuellen Durchlaufs. Achte darauf, dass while-Schleifen ihre Bedingung irgendwann ändern.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const namen = [&quot;Ava&quot;, &quot;Ben&quot;, &quot;Chris&quot;];\nfor (const name of namen) {\n  console.log(name);\n}\nlet zahl = 1;\nwhile (zahl &lt;= 3) {\n  console.log(zahl);\n  zahl++;\n}</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Ava\nBen\nChris\n1\n2\n3</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Schreibe eine while-Schleife, die von 5 bis 1 herunterzählt.</div>"},{"title":"Scope, Arrow Functions & Closures","short":"Scope & Arrow Functions","desc":"Lerne Gültigkeitsbereiche und kompakte Funktionssyntax kennen.","goals":["Du verstehst Block-Scope","Du schreibst Arrow Functions","Du kennst Closures als Konzept"],"section":"Wo Variablen gültig sind","body":"Der Scope bestimmt, wo eine Variable erreichbar ist. let und const sind auf ihren Block begrenzt. Arrow Functions schreiben Funktionen kompakt: const doppelt = zahl => zahl * 2. Eine Closure entsteht, wenn eine Funktion auf Variablen aus ihrem äußeren Gültigkeitsbereich zugreifen kann, auch nachdem der äußere Aufruf beendet wurde.","example":"const doppelt = zahl => zahl * 2;\nconsole.log(doppelt(7));\nfunction zaehlerStarten() {\n  let wert = 0;\n  return () => ++wert;\n}\nconst naechsterWert = zaehlerStarten();\nconsole.log(naechsterWert());\nconsole.log(naechsterWert());","expected":"14\n1\n2","task":"Schreibe eine Arrow Function quadrat, die eine Zahl quadriert.","quiz":{"q":"Welche Variable ist nur innerhalb eines mit { } angelegten Blocks verfügbar, wenn sie dort deklariert wird?","opts":["Eine mit let deklarierte Variable","Jede globale Variable","Eine HTML-ID"],"correct":0,"explain":"let und const besitzen Block-Scope."},"explanation":"<p>Der Scope bestimmt, wo eine Variable erreichbar ist. let und const sind auf ihren Block begrenzt. Arrow Functions schreiben Funktionen kompakt: const doppelt = zahl => zahl * 2. Eine Closure entsteht, wenn eine Funktion auf Variablen aus ihrem äußeren Gültigkeitsbereich zugreifen kann, auch nachdem der äußere Aufruf beendet wurde.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const doppelt = zahl =&gt; zahl * 2;\nconsole.log(doppelt(7));\nfunction zaehlerStarten() {\n  let wert = 0;\n  return () =&gt; ++wert;\n}\nconst naechsterWert = zaehlerStarten();\nconsole.log(naechsterWert());\nconsole.log(naechsterWert());</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">14\n1\n2</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Schreibe eine Arrow Function quadrat, die eine Zahl quadriert.</div>"},{"title":"Array-Methoden","short":"map, filter, find, reduce","desc":"Verarbeite Arrays ohne jede Schleife manuell schreiben zu müssen.","goals":["Du nutzt map()","Du filterst mit filter()","Du findest Werte und berechnest Summen"],"section":"Listen elegant verarbeiten","body":"map() erzeugt ein neues Array mit umgewandelten Elementen. filter() behält Elemente, die eine Bedingung erfüllen. find() liefert das erste passende Element. reduce() fasst viele Werte zu einem Ergebnis zusammen. Diese Methoden verändern das ursprüngliche Array in der Regel nicht.","example":"const zahlen = [1, 2, 3, 4];\nconsole.log(zahlen.map(n => n * 3));\nconsole.log(zahlen.filter(n => n % 2 === 0));\nconsole.log(zahlen.find(n => n > 2));\nconsole.log(zahlen.reduce((summe, n) => summe + n, 0));","expected":"[3,6,9,12]\n[2,4]\n3\n10","task":"Filtere aus [5, 10, 15, 20] alle Zahlen größer als 10 heraus.","quiz":{"q":"Welche Methode erzeugt ein neues Array mit umgewandelten Werten?","opts":["find()","map()","reduce()"],"correct":1,"explain":"map() bildet jedes Element auf einen neuen Wert ab."},"explanation":"<p>map() erzeugt ein neues Array mit umgewandelten Elementen. filter() behält Elemente, die eine Bedingung erfüllen. find() liefert das erste passende Element. reduce() fasst viele Werte zu einem Ergebnis zusammen. Diese Methoden verändern das ursprüngliche Array in der Regel nicht.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const zahlen = [1, 2, 3, 4];\nconsole.log(zahlen.map(n =&gt; n * 3));\nconsole.log(zahlen.filter(n =&gt; n % 2 === 0));\nconsole.log(zahlen.find(n =&gt; n &gt; 2));\nconsole.log(zahlen.reduce((summe, n) =&gt; summe + n, 0));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">[3,6,9,12]\n[2,4]\n3\n10</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Filtere aus [5, 10, 15, 20] alle Zahlen größer als 10 heraus.</div>"},{"title":"Strings & Template Literals","short":"Strings & Texte","desc":"Bearbeite Text und setze Variablen in Zeichenketten ein.","goals":["Du nutzt Template Literals","Du kennst trim und includes","Du kannst Text in Groß-/Kleinschreibung ändern"],"section":"Text verarbeiten","body":"Template Literals verwenden Backticks und erlauben Einbettungen mit ${...}. trim() entfernt Leerzeichen am Anfang und Ende. includes() prüft, ob ein Teiltext vorkommt. toUpperCase() und toLowerCase() ändern die Groß-/Kleinschreibung, ohne den ursprünglichen String zu verändern.","example":"const vorname = \"Mira\";\nconst begruessung = `Hallo, ${vorname}!`;\nconsole.log(begruessung);\nconsole.log(\"  JavaScript  \".trim());\nconsole.log(\"Lernpfad\".includes(\"pfad\"));","expected":"Hallo, Mira!\nJavaScript\ntrue","task":"Erstelle mit einem Template Literal eine Begrüßung mit deinem eigenen Namen.","quiz":{"q":"Welche Methode entfernt Leerzeichen am Anfang und Ende?","opts":["slice()","trim()","push()"],"correct":1,"explain":"trim() entfernt äußere Leerzeichen."},"explanation":"<p>Template Literals verwenden Backticks und erlauben Einbettungen mit ${...}. trim() entfernt Leerzeichen am Anfang und Ende. includes() prüft, ob ein Teiltext vorkommt. toUpperCase() und toLowerCase() ändern die Groß-/Kleinschreibung, ohne den ursprünglichen String zu verändern.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const vorname = &quot;Mira&quot;;\nconst begruessung = `Hallo, ${vorname}!`;\nconsole.log(begruessung);\nconsole.log(&quot;  JavaScript  &quot;.trim());\nconsole.log(&quot;Lernpfad&quot;.includes(&quot;pfad&quot;));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Hallo, Mira!\nJavaScript\ntrue</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erstelle mit einem Template Literal eine Begrüßung mit deinem eigenen Namen.</div>"},{"title":"Destructuring & Spread","short":"Daten bequem entpacken","desc":"Entpacke Arrays und Objekte und erstelle Kopien mit Spread-Syntax.","goals":["Du nutzt Objekt-Destructuring","Du entpackst Arrays","Du verstehst Spread-Syntax"],"section":"Werte übersichtlich übernehmen","body":"Destructuring übernimmt Werte aus Arrays oder Objekten in Variablen. Der Spread-Operator ... kann Elemente in ein neues Array oder Eigenschaften in ein neues Objekt kopieren. Das ist eine flache Kopie: Verschachtelte Objekte werden nicht automatisch tief kopiert.","example":"const person = { name: \"Lea\", alter: 31 };\nconst { name, alter } = person;\nconsole.log(name, alter);\nconst basis = [1, 2];\nconst erweitert = [...basis, 3, 4];\nconsole.log(erweitert);","expected":"Lea 31\n[1,2,3,4]","task":"Kopiere ein Array [\"HTML\", \"CSS\"] mit Spread und füge \"JavaScript\" hinzu.","quiz":{"q":"Wofür wird ... in einem Array-Ausdruck häufig verwendet?","opts":["Zum Kopieren/Erweitern von Arrays","Zum Vergleichen von Typen","Zum Erstellen eines Kommentars"],"correct":0,"explain":"Spread verteilt die Elemente eines iterierbaren Wertes in einen neuen Ausdruck."},"explanation":"<p>Destructuring übernimmt Werte aus Arrays oder Objekten in Variablen. Der Spread-Operator ... kann Elemente in ein neues Array oder Eigenschaften in ein neues Objekt kopieren. Das ist eine flache Kopie: Verschachtelte Objekte werden nicht automatisch tief kopiert.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const person = { name: &quot;Lea&quot;, alter: 31 };\nconst { name, alter } = person;\nconsole.log(name, alter);\nconst basis = [1, 2];\nconst erweitert = [...basis, 3, 4];\nconsole.log(erweitert);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Lea 31\n[1,2,3,4]</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Kopiere ein Array [\"HTML\", \"CSS\"] mit Spread und füge \"JavaScript\" hinzu.</div>"},{"title":"Datum & Zeit","short":"Date","desc":"Erzeuge Datumswerte und berechne einfache Zeitabstände.","goals":["Du erstellst Date-Objekte","Du liest Jahr und Monat aus","Du verstehst Zeitzonen als Stolperfalle"],"section":"Mit Zeitwerten arbeiten","body":"Date repräsentiert einen Zeitpunkt. getFullYear() liefert das Jahr, getMonth() liefert den Monat von 0 bis 11. Für menschenlesbare Datumswerte ist toLocaleDateString() nützlich. Bei Zeitangaben können Zeitzonen eine Rolle spielen; speichere Zeitpunkte in Anwendungen möglichst eindeutig.","example":"const datum = new Date(\"2026-10-26T12:00:00\");\nconsole.log(datum.getFullYear());\nconsole.log(datum.getMonth() + 1);\nconsole.log(datum.toLocaleDateString(\"de-DE\"));","expected":"2026\n10\n26.10.2026","task":"Erzeuge ein Date-Objekt und gib das aktuelle Jahr aus.","quiz":{"q":"Welchen Bereich hat getMonth() bei JavaScript-Date-Objekten?","opts":["1 bis 12","0 bis 11","0 bis 30"],"correct":1,"explain":"getMonth() ist nullbasiert: Januar ist 0 und Dezember 11."},"explanation":"<p>Date repräsentiert einen Zeitpunkt. getFullYear() liefert das Jahr, getMonth() liefert den Monat von 0 bis 11. Für menschenlesbare Datumswerte ist toLocaleDateString() nützlich. Bei Zeitangaben können Zeitzonen eine Rolle spielen; speichere Zeitpunkte in Anwendungen möglichst eindeutig.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const datum = new Date(&quot;2026-10-26T12:00:00&quot;);\nconsole.log(datum.getFullYear());\nconsole.log(datum.getMonth() + 1);\nconsole.log(datum.toLocaleDateString(&quot;de-DE&quot;));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">2026\n10\n26.10.2026</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erzeuge ein Date-Objekt und gib das aktuelle Jahr aus.</div>"},{"title":"Fehlerbehandlung","short":"try...catch","desc":"Fange Laufzeitfehler ab und gib verständliche Meldungen aus.","goals":["Du nutzt try und catch","Du liest Fehlermeldungen","Du kennst finally"],"section":"Fehler kontrolliert behandeln","body":"try führt Code aus, der fehlschlagen könnte. catch verarbeitet einen geworfenen Fehler. finally wird unabhängig davon ausgeführt, ob ein Fehler auftrat. Fehlerbehandlung ersetzt keine Prüfung der Eingaben, macht aber Fehler kontrollierbarer.","example":"try {\n  const daten = JSON.parse(\"{ kaputt }\");\n  console.log(daten);\n} catch (fehler) {\n  console.log(\"Daten konnten nicht gelesen werden.\");\n  console.log(fehler.name);\n} finally {\n  console.log(\"Prüfung beendet.\");\n}","expected":"Daten konnten nicht gelesen werden.\nSyntaxError\nPrüfung beendet.","task":"Verpacke JSON.parse(\"{ kaputt }\") in try...catch und gib eine eigene Fehlermeldung aus.","quiz":{"q":"Welcher Block wird auch nach einem Fehler ausgeführt, wenn er vorhanden ist?","opts":["catch","finally","return"],"correct":1,"explain":"finally wird unabhängig vom Fehlerfall ausgeführt."},"explanation":"<p>try führt Code aus, der fehlschlagen könnte. catch verarbeitet einen geworfenen Fehler. finally wird unabhängig davon ausgeführt, ob ein Fehler auftrat. Fehlerbehandlung ersetzt keine Prüfung der Eingaben, macht aber Fehler kontrollierbarer.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">try {\n  const daten = JSON.parse(&quot;{ kaputt }&quot;);\n  console.log(daten);\n} catch (fehler) {\n  console.log(&quot;Daten konnten nicht gelesen werden.&quot;);\n  console.log(fehler.name);\n} finally {\n  console.log(&quot;Prüfung beendet.&quot;);\n}</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Daten konnten nicht gelesen werden.\nSyntaxError\nPrüfung beendet.</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Verpacke JSON.parse(\"{ kaputt }\") in try...catch und gib eine eigene Fehlermeldung aus.</div>"},{"title":"JSON & lokale Speicherung","short":"JSON & localStorage","desc":"Wandle Daten in JSON um und speichere einfache Werte im Browser.","goals":["Du nutzt JSON.stringify()","Du nutzt JSON.parse()","Du speicherst Daten in localStorage"],"section":"Daten über Sitzungen behalten","body":"JSON ist ein Textformat für strukturierte Daten. JSON.stringify() wandelt geeignete Werte in Text um; JSON.parse() liest gültigen JSON-Text. localStorage speichert Schlüssel-Wert-Paare als Strings im Browser. Speichere dort keine Passwörter oder sensiblen Daten.","example":"const aufgaben = [{ titel: \"Lernen\", erledigt: false }];\nconst text = JSON.stringify(aufgaben);\nconst geladen = JSON.parse(text);\nconsole.log(text);\nconsole.log(geladen[0].titel);","expected":"[{\"titel\":\"Lernen\",\"erledigt\":false}]\nLernen","task":"Speichere ein Objekt als JSON-Text und lies es anschließend wieder aus.","quiz":{"q":"Welche Methode wandelt ein Objekt in JSON-Text um?","opts":["JSON.parse()","JSON.stringify()","localStorage.getItem()"],"correct":1,"explain":"JSON.stringify() serialisiert einen Wert in JSON-Text."},"explanation":"<p>JSON ist ein Textformat für strukturierte Daten. JSON.stringify() wandelt geeignete Werte in Text um; JSON.parse() liest gültigen JSON-Text. localStorage speichert Schlüssel-Wert-Paare als Strings im Browser. Speichere dort keine Passwörter oder sensiblen Daten.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const aufgaben = [{ titel: &quot;Lernen&quot;, erledigt: false }];\nconst text = JSON.stringify(aufgaben);\nconst geladen = JSON.parse(text);\nconsole.log(text);\nconsole.log(geladen[0].titel);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">[{&quot;titel&quot;:&quot;Lernen&quot;,&quot;erledigt&quot;:false}]\nLernen</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Speichere ein Objekt als JSON-Text und lies es anschließend wieder aus.</div>"},{"title":"DOM praktisch einsetzen","short":"DOM-Manipulation","desc":"Erstelle HTML-Elemente und ändere Inhalte direkt im Browser.","goals":["Du nutzt createElement()","Du setzt textContent","Du hängst Elemente mit append() an"],"section":"HTML mit JavaScript erzeugen","body":"Das DOM ist die Objektstruktur einer Webseite. querySelector() findet Elemente, createElement() erstellt ein Element und textContent setzt sicheren Textinhalt. append() fügt ein Element ein. In dieser Lektion erzeugt der Code sein eigenes kleines DOM-Beispiel im isolierten Ausführungsfenster.","example":"document.body.innerHTML = \"\";\nconst titel = document.createElement(\"h2\");\ntitel.textContent = \"Meine dynamische Überschrift\";\ndocument.body.append(titel);\nconsole.log(titel.textContent);","expected":"Meine dynamische Überschrift","task":"Erzeuge ein <p>-Element, setze seinen Text und füge es mit append() in document.body ein.","quiz":{"q":"Welche Eigenschaft eignet sich zum Setzen von reinem Text in ein Element?","opts":["innerHTML","textContent","classList"],"correct":1,"explain":"textContent behandelt den Inhalt als Text und interpretiert ihn nicht als HTML."},"explanation":"<p>Das DOM ist die Objektstruktur einer Webseite. querySelector() findet Elemente, createElement() erstellt ein Element und textContent setzt sicheren Textinhalt. append() fügt ein Element ein. In dieser Lektion erzeugt der Code sein eigenes kleines DOM-Beispiel im isolierten Ausführungsfenster.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">document.body.innerHTML = &quot;&quot;;\nconst titel = document.createElement(&quot;h2&quot;);\ntitel.textContent = &quot;Meine dynamische Überschrift&quot;;\ndocument.body.append(titel);\nconsole.log(titel.textContent);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Meine dynamische Überschrift</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erzeuge ein <p>-Element, setze seinen Text und füge es mit append() in document.body ein.</div>"},{"title":"Events & Formulare","short":"Interaktionen und Validierung","desc":"Reagiere auf Ereignisse und prüfe Benutzereingaben.","goals":["Du kennst addEventListener()","Du verstehst submit","Du prüfst Eingaben vor der Verarbeitung"],"section":"Ereignisse sicher verarbeiten","body":"addEventListener() registriert einen Handler für ein Ereignis. Bei Formularen ist submit meist der richtige Zeitpunkt zum Prüfen. Im echten Browser kannst du mit preventDefault() das Standard-Absenden verhindern, wenn die Eingaben ungültig sind. Gib Benutzereingaben nicht ungeprüft als HTML aus.","example":"document.body.innerHTML = \"<button id=\"knopf\">Klick mich</button>\";\nconst knopf = document.querySelector(\"#knopf\");\nknopf.addEventListener(\"click\", () => console.log(\"Klick erkannt\"));\nknopf.click();","expected":"Klick erkannt","task":"Erstelle einen Button, registriere einen click-Handler und lasse den Button per click() auslösen.","quiz":{"q":"Welche Methode registriert einen Ereignis-Handler?","opts":["addEventListener()","querySelectorAll()","JSON.parse()"],"correct":0,"explain":"addEventListener() verbindet ein Ereignis mit einer Funktion."},"explanation":"<p>addEventListener() registriert einen Handler für ein Ereignis. Bei Formularen ist submit meist der richtige Zeitpunkt zum Prüfen. Im echten Browser kannst du mit preventDefault() das Standard-Absenden verhindern, wenn die Eingaben ungültig sind. Gib Benutzereingaben nicht ungeprüft als HTML aus.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">document.body.innerHTML = &quot;&lt;button id=&quot;knopf&quot;&gt;Klick mich&lt;/button&gt;&quot;;\nconst knopf = document.querySelector(&quot;#knopf&quot;);\nknopf.addEventListener(&quot;click&quot;, () =&gt; console.log(&quot;Klick erkannt&quot;));\nknopf.click();</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Klick erkannt</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erstelle einen Button, registriere einen click-Handler und lasse den Button per click() auslösen.</div>"},{"title":"Asynchrones JavaScript","short":"Promises & async/await","desc":"Verstehe verzögerte Ergebnisse und asynchrone Abläufe.","goals":["Du erkennst Promises","Du nutzt async und await","Du behandelst asynchrone Fehler"],"section":"Auf Ergebnisse warten","body":"Asynchrone Operationen liefern ihr Ergebnis nicht immer sofort. Ein Promise repräsentiert einen später erfüllten oder abgelehnten Vorgang. async macht eine Funktion asynchron; await wartet innerhalb dieser Funktion auf ein Promise. Fehler lassen sich mit try...catch behandeln.","example":"const warte = ms => new Promise(resolve => setTimeout(resolve, ms));\nasync function start() {\n  console.log(\"Start\");\n  await warte(100);\n  console.log(\"Nach kurzer Pause\");\n}\nstart();","expected":"Start\nNach kurzer Pause","task":"Erstelle eine async-Funktion, die mit await auf ein Promise wartet und danach eine Meldung ausgibt.","quiz":{"q":"Wo darf await in der üblichen Syntax verwendet werden?","opts":["Innerhalb einer async-Funktion","Nur in CSS","Nur in einem Kommentar"],"correct":0,"explain":"await wird in einer async-Funktion verwendet; moderne Umgebungen unterstützen zusätzlich Top-Level-await in Modulen."},"explanation":"<p>Asynchrone Operationen liefern ihr Ergebnis nicht immer sofort. Ein Promise repräsentiert einen später erfüllten oder abgelehnten Vorgang. async macht eine Funktion asynchron; await wartet innerhalb dieser Funktion auf ein Promise. Fehler lassen sich mit try...catch behandeln.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const warte = ms =&gt; new Promise(resolve =&gt; setTimeout(resolve, ms));\nasync function start() {\n  console.log(&quot;Start&quot;);\n  await warte(100);\n  console.log(&quot;Nach kurzer Pause&quot;);\n}\nstart();</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Start\nNach kurzer Pause</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erstelle eine async-Funktion, die mit await auf ein Promise wartet und danach eine Meldung ausgibt.</div>"},{"title":"APIs & fetch","short":"Daten von Diensten abrufen","desc":"Lerne HTTP, fetch und die Verarbeitung von API-Antworten kennen.","goals":["Du verstehst Request und Response","Du kennst response.json()","Du behandelst Netzwerkfehler"],"section":"Externe Daten nutzen","body":"Eine API stellt Funktionen oder Daten über eine definierte Schnittstelle bereit. fetch() sendet eine HTTP-Anfrage und liefert ein Promise mit einer Response. Prüfe response.ok, bevor du JSON ausliest. Netzwerkzugriff kann in Offline-Dateien, durch CORS-Regeln oder fehlende API-Schlüssel scheitern.","example":"async function beispiel() {\n  const antwort = { ok: true, status: 200 };\n  if (!antwort.ok) throw new Error(\"Anfrage fehlgeschlagen\");\n  console.log(\"HTTP-Status:\", antwort.status);\n}\nbeispiel();","expected":"HTTP-Status: 200","task":"Erkläre in einem Kommentar, warum response.ok geprüft werden sollte, bevor response.json() aufgerufen wird.","quiz":{"q":"Was liefert fetch() zunächst zurück?","opts":["Direkt ein fertiges Array","Ein Promise mit einer Response","Immer eine Zeichenkette"],"correct":1,"explain":"fetch() liefert ein Promise, das mit einem Response-Objekt erfüllt wird. Die Anfrage selbst benötigt Internetzugriff und kann fehlschlagen."},"explanation":"<p>Eine API stellt Funktionen oder Daten über eine definierte Schnittstelle bereit. fetch() sendet eine HTTP-Anfrage und liefert ein Promise mit einer Response. Prüfe response.ok, bevor du JSON ausliest. Netzwerkzugriff kann in Offline-Dateien, durch CORS-Regeln oder fehlende API-Schlüssel scheitern.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">async function beispiel() {\n  const antwort = { ok: true, status: 200 };\n  if (!antwort.ok) throw new Error(&quot;Anfrage fehlgeschlagen&quot;);\n  console.log(&quot;HTTP-Status:&quot;, antwort.status);\n}\nbeispiel();</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">HTTP-Status: 200</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erkläre in einem Kommentar, warum response.ok geprüft werden sollte, bevor response.json() aufgerufen wird.</div>"},{"title":"Module & Codeorganisation","short":"import und export","desc":"Teile größere Programme in wiederverwendbare Dateien auf.","goals":["Du verstehst export","Du kennst import","Du erkennst den Nutzen kleiner Module"],"section":"Code in Dateien aufteilen","body":"Module teilen ein Programm in Dateien mit klaren Aufgaben. export macht Funktionen oder Werte verfügbar; import bindet sie an anderer Stelle ein. Import-Anweisungen brauchen normalerweise Module und laufen nicht in jedem einfachen Skript-Kontext. Der Academy-Editor zeigt die Syntax, das Beispiel darunter demonstriert das Prinzip mit einer Funktion.","example":"// datei: rechner.js\nexport function addiere(a, b) {\n  return a + b;\n}\n\n// datei: main.js\n// import { addiere } from \"./rechner.js\";\nconsole.log(\"Ergebnis einer modularen Funktion:\", 4 + 6);","expected":"Ergebnis einer modularen Funktion: 10","task":"Lege gedanklich eine Datei begruessung.js an und notiere eine exportierte Funktion begruessen(name).","quiz":{"q":"Welches Schlüsselwort stellt einen benannten Export bereit?","opts":["import","export","requireHTML"],"correct":1,"explain":"export stellt Werte aus einem ES-Modul bereit."},"explanation":"<p>Module teilen ein Programm in Dateien mit klaren Aufgaben. export macht Funktionen oder Werte verfügbar; import bindet sie an anderer Stelle ein. Import-Anweisungen brauchen normalerweise Module und laufen nicht in jedem einfachen Skript-Kontext. Der Academy-Editor zeigt die Syntax, das Beispiel darunter demonstriert das Prinzip mit einer Funktion.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">// datei: rechner.js\nexport function addiere(a, b) {\n  return a + b;\n}\n\n// datei: main.js\n// import { addiere } from &quot;./rechner.js&quot;;\nconsole.log(&quot;Ergebnis einer modularen Funktion:&quot;, 4 + 6);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Ergebnis einer modularen Funktion: 10</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Lege gedanklich eine Datei begruessung.js an und notiere eine exportierte Funktion begruessen(name).</div>"},{"title":"Klassen & objektorientierte Programmierung","short":"Klassen & this","desc":"Erstelle Objekte aus Klassen und bündele Daten und Verhalten.","goals":["Du schreibst eine class","Du verwendest constructor","Du verstehst Methoden und this"],"section":"Objekte aus Bauplänen erstellen","body":"Eine Klasse beschreibt, wie Objekte aufgebaut sind. constructor initialisiert neue Instanzen. Methoden bündeln Verhalten; this verweist in einer Instanzmethode typischerweise auf das aktuelle Objekt. Klassen sind Syntax über dem prototypischen Vererbungsmodell von JavaScript.","example":"class Konto {\n  constructor(stand) { this.stand = stand; }\n  einzahlen(betrag) { this.stand += betrag; }\n}\nconst konto = new Konto(10);\nkonto.einzahlen(5);\nconsole.log(konto.stand);","expected":"15","task":"Erstelle eine Klasse Produkt mit einem Namen und einer Methode, die den Namen ausgibt.","quiz":{"q":"Wofür wird constructor verwendet?","opts":["Zum Initialisieren einer Instanz","Zum Importieren von CSS","Zum Beenden einer Schleife"],"correct":0,"explain":"constructor wird beim Erzeugen einer neuen Instanz zur Initialisierung aufgerufen."},"explanation":"<p>Eine Klasse beschreibt, wie Objekte aufgebaut sind. constructor initialisiert neue Instanzen. Methoden bündeln Verhalten; this verweist in einer Instanzmethode typischerweise auf das aktuelle Objekt. Klassen sind Syntax über dem prototypischen Vererbungsmodell von JavaScript.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">class Konto {\n  constructor(stand) { this.stand = stand; }\n  einzahlen(betrag) { this.stand += betrag; }\n}\nconst konto = new Konto(10);\nkonto.einzahlen(5);\nconsole.log(konto.stand);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">15</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erstelle eine Klasse Produkt mit einem Namen und einer Methode, die den Namen ausgibt.</div>"},{"title":"Reguläre Ausdrücke","short":"Regex","desc":"Prüfe einfache Textmuster mit regulären Ausdrücken.","goals":["Du nutzt test()","Du verstehst Muster und Flags","Du kennst Grenzen der Regex-Validierung"],"section":"Muster in Texten erkennen","body":"Reguläre Ausdrücke beschreiben Textmuster. Die Methode test() prüft, ob ein String zum Muster passt. Sie eignen sich für einfache Formatprüfungen, ersetzen aber nicht in jedem Fall eine vollständige fachliche Validierung, zum Beispiel bei E-Mail-Adressen.","example":"const nurZiffern = /^\\d+$/;\nconsole.log(nurZiffern.test(\"12345\"));\nconsole.log(nurZiffern.test(\"12a45\"));","expected":"true\nfalse","task":"Erstelle einen regulären Ausdruck, der prüft, ob ein Text nur aus Kleinbuchstaben besteht.","quiz":{"q":"Was prüft RegExp.prototype.test()?","opts":["Ob ein Muster passt","Ob ein Array sortiert ist","Ob eine Datei gespeichert wurde"],"correct":0,"explain":"test() liefert true, wenn das Muster im String gefunden wird."},"explanation":"<p>Reguläre Ausdrücke beschreiben Textmuster. Die Methode test() prüft, ob ein String zum Muster passt. Sie eignen sich für einfache Formatprüfungen, ersetzen aber nicht in jedem Fall eine vollständige fachliche Validierung, zum Beispiel bei E-Mail-Adressen.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const nurZiffern = /^\\d+$/;\nconsole.log(nurZiffern.test(&quot;12345&quot;));\nconsole.log(nurZiffern.test(&quot;12a45&quot;));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">true\nfalse</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erstelle einen regulären Ausdruck, der prüft, ob ein Text nur aus Kleinbuchstaben besteht.</div>"},{"title":"Debugging mit DevTools","short":"Fehler systematisch finden","desc":"Nutze Konsole, Breakpoints und schrittweise Prüfung.","goals":["Du unterscheidest Syntax- und Laufzeitfehler","Du liest Stack-Traces","Du kennst Breakpoints"],"section":"Nicht raten, sondern prüfen","body":"Debugging bedeutet, den tatsächlichen Grund eines Fehlers zu finden. Lies die erste aussagekräftige Fehlermeldung, prüfe Zeile und Stack-Trace und reduziere das Problem auf einen kleinen reproduzierbaren Fall. Breakpoints halten die Ausführung an, damit du Variablen und den Call Stack untersuchen kannst.","example":"const preis = 19.99;\nconst anzahl = 3;\nconst summe = preis * anzahl;\nconsole.log(\"Einzelpreis:\", preis);\nconsole.log(\"Anzahl:\", anzahl);\nconsole.log(\"Summe:\", summe);","expected":"Einzelpreis: 19.99\nAnzahl: 3\nSumme: 59.97","task":"Füge absichtlich einen Variablennamen falsch ein, führe den Code aus und korrigiere ihn anhand der Fehlermeldung.","quiz":{"q":"Was ist ein Breakpoint?","opts":["Ein Haltepunkt im Debugger","Ein CSS-Selektor","Ein Datentyp"],"correct":0,"explain":"Ein Breakpoint pausiert die Ausführung an einer festgelegten Stelle."},"explanation":"<p>Debugging bedeutet, den tatsächlichen Grund eines Fehlers zu finden. Lies die erste aussagekräftige Fehlermeldung, prüfe Zeile und Stack-Trace und reduziere das Problem auf einen kleinen reproduzierbaren Fall. Breakpoints halten die Ausführung an, damit du Variablen und den Call Stack untersuchen kannst.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const preis = 19.99;\nconst anzahl = 3;\nconst summe = preis * anzahl;\nconsole.log(&quot;Einzelpreis:&quot;, preis);\nconsole.log(&quot;Anzahl:&quot;, anzahl);\nconsole.log(&quot;Summe:&quot;, summe);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Einzelpreis: 19.99\nAnzahl: 3\nSumme: 59.97</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Füge absichtlich einen Variablennamen falsch ein, führe den Code aus und korrigiere ihn anhand der Fehlermeldung.</div>"},{"title":"Tests & Qualität","short":"Funktionen testen","desc":"Prüfe, ob Funktionen für verschiedene Eingaben korrekte Ergebnisse liefern.","goals":["Du schreibst einfache Assertions","Du testest Normal- und Grenzfälle","Du verstehst reproduzierbare Tests"],"section":"Erwartungen überprüfbar machen","body":"Ein Test vergleicht ein tatsächliches Ergebnis mit einem erwarteten Ergebnis. Teste normale Eingaben, Grenzfälle und ungültige Werte. Automatisierte Tests machen Regressionen sichtbar, wenn du später Code änderst.","example":"function addiere(a, b) { return a + b; }\nfunction assertGleich(ist, erwartet) {\n  if (ist !== erwartet) throw new Error(`Erwartet ${erwartet}, erhalten ${ist}`);\n  console.log(\"Test bestanden:\", ist);\n}\nassertGleich(addiere(2, 3), 5);\nassertGleich(addiere(-1, 1), 0);","expected":"Test bestanden: 5\nTest bestanden: 0","task":"Schreibe zwei Tests für eine Funktion, die eine Zahl verdoppelt.","quiz":{"q":"Was sollte ein guter Test vergleichen?","opts":["Zufällige Werte ohne Erwartung","Tatsächliches und erwartetes Ergebnis","Nur die Anzahl der Codezeilen"],"correct":1,"explain":"Tests brauchen eine überprüfbare Erwartung."},"explanation":"<p>Ein Test vergleicht ein tatsächliches Ergebnis mit einem erwarteten Ergebnis. Teste normale Eingaben, Grenzfälle und ungültige Werte. Automatisierte Tests machen Regressionen sichtbar, wenn du später Code änderst.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">function addiere(a, b) { return a + b; }\nfunction assertGleich(ist, erwartet) {\n  if (ist !== erwartet) throw new Error(`Erwartet ${erwartet}, erhalten ${ist}`);\n  console.log(&quot;Test bestanden:&quot;, ist);\n}\nassertGleich(addiere(2, 3), 5);\nassertGleich(addiere(-1, 1), 0);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Test bestanden: 5\nTest bestanden: 0</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Schreibe zwei Tests für eine Funktion, die eine Zahl verdoppelt.</div>"},{"title":"Sicherheit im Browser","short":"Sichere DOM-Manipulation","desc":"Vermeide typische Risiken beim Umgang mit Benutzereingaben.","goals":["Du verstehst XSS als Risiko","Du bevorzugst textContent für Text","Du validierst Eingaben"],"section":"Eingaben als nicht vertrauenswürdig behandeln","body":"XSS kann entstehen, wenn nicht vertrauenswürdige Eingaben als ausführbares HTML interpretiert werden. Verwende für reinen Text textContent statt innerHTML. Validierung sollte serverseitig wiederholt werden, wenn Daten an einen Server gehen. Speichere keine Geheimnisse im Frontend oder in localStorage.","example":"const benutzereingabe = \"<img src=x onerror=alert(1)>\";\nconst ausgabe = document.createElement(\"p\");\nausgabe.textContent = benutzereingabe;\nconsole.log(\"Eingabe wird als Text behandelt:\", ausgabe.textContent);","expected":"Eingabe wird als Text behandelt: <img src=x onerror=alert(1)>","task":"Erkläre, warum textContent für eine Nutzereingabe sicherer ist als ungeprüftes innerHTML.","quiz":{"q":"Welche Eigenschaft eignet sich für reinen Text?","opts":["textContent","innerHTML ohne Prüfung","eval()"],"correct":0,"explain":"textContent interpretiert die Eingabe nicht als HTML-Markup."},"explanation":"<p>XSS kann entstehen, wenn nicht vertrauenswürdige Eingaben als ausführbares HTML interpretiert werden. Verwende für reinen Text textContent statt innerHTML. Validierung sollte serverseitig wiederholt werden, wenn Daten an einen Server gehen. Speichere keine Geheimnisse im Frontend oder in localStorage.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const benutzereingabe = &quot;&lt;img src=x onerror=alert(1)&gt;&quot;;\nconst ausgabe = document.createElement(&quot;p&quot;);\nausgabe.textContent = benutzereingabe;\nconsole.log(&quot;Eingabe wird als Text behandelt:&quot;, ausgabe.textContent);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Eingabe wird als Text behandelt: &lt;img src=x onerror=alert(1)&gt;</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Erkläre, warum textContent für eine Nutzereingabe sicherer ist als ungeprüftes innerHTML.</div>"},{"title":"Performance & Barrierefreiheit","short":"Schneller und zugänglicher Code","desc":"Verbessere Effizienz und Bedienbarkeit deiner Webanwendungen.","goals":["Du vermeidest unnötige DOM-Arbeit","Du verstehst Fokus und Tastaturbedienung","Du kennst semantische HTML-Elemente"],"section":"An alle Nutzenden denken","body":"Vermeide unnötig häufige DOM-Änderungen und wiederholte Berechnungen in großen Schleifen. Für Barrierefreiheit brauchen interaktive Elemente eine sinnvolle Semantik, sichtbaren Fokus und Tastaturbedienbarkeit. Nutze echte Buttons für Aktionen und beschrifte Eingabefelder verständlich.","example":"const werte = [12, 8, 20, 5];\nconst summe = werte.reduce((a, b) => a + b, 0);\nconsole.log(\"Summe:\", summe);\nconsole.log(\"Mittelwert:\", summe / werte.length);","expected":"Summe: 45\nMittelwert: 11.25","task":"Prüfe eine selbst gebaute Schaltfläche: Ist sie per Tastatur erreichbar und verständlich beschriftet?","quiz":{"q":"Was ist für eine zugängliche Aktion normalerweise die beste Wahl?","opts":["Ein klickbares div ohne Rolle","Ein echtes button-Element","Ein Bild ohne Text"],"correct":1,"explain":"Ein echtes button-Element besitzt passende Semantik und Tastaturbedienung bereits eingebaut."},"explanation":"<p>Vermeide unnötig häufige DOM-Änderungen und wiederholte Berechnungen in großen Schleifen. Für Barrierefreiheit brauchen interaktive Elemente eine sinnvolle Semantik, sichtbaren Fokus und Tastaturbedienbarkeit. Nutze echte Buttons für Aktionen und beschrifte Eingabefelder verständlich.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const werte = [12, 8, 20, 5];\nconst summe = werte.reduce((a, b) =&gt; a + b, 0);\nconsole.log(&quot;Summe:&quot;, summe);\nconsole.log(&quot;Mittelwert:&quot;, summe / werte.length);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Summe: 45\nMittelwert: 11.25</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Prüfe eine selbst gebaute Schaltfläche: Ist sie per Tastatur erreichbar und verständlich beschriftet?</div>"},{"title":"Projekt: To-do-Liste","short":"Projekt To-do","desc":"Kombiniere Arrays, Objekte, Funktionen und lokale Speicherung.","goals":["Du modellierst Aufgaben als Objekte","Du kannst Aufgaben filtern","Du speicherst Aufgaben lokal"],"section":"Eine kleine Aufgabenverwaltung planen","body":"Eine To-do-Liste kann Aufgaben als Objekte mit id, titel und erledigt speichern. Funktionen zum Hinzufügen, Abhaken und Löschen halten die Logik getrennt. In einer vollständigen Web-App wird die Liste im DOM gerendert und mit localStorage gespeichert.","example":"const aufgaben = [\n  { titel: \"Grundlagen lernen\", erledigt: true },\n  { titel: \"Array-Methoden üben\", erledigt: false }\n];\nconst offen = aufgaben.filter(a => !a.erledigt);\nconsole.log(offen.map(a => a.titel));","expected":"[\"Array-Methoden üben\"]","task":"Ergänze eine dritte Aufgabe und gib nur die offenen Aufgaben aus.","quiz":{"q":"Welche Methode eignet sich, um offene Aufgaben herauszufiltern?","opts":["map()","filter()","join()"],"correct":1,"explain":"filter() behält nur Elemente, deren Bedingung true ergibt."},"explanation":"<p>Eine To-do-Liste kann Aufgaben als Objekte mit id, titel und erledigt speichern. Funktionen zum Hinzufügen, Abhaken und Löschen halten die Logik getrennt. In einer vollständigen Web-App wird die Liste im DOM gerendert und mit localStorage gespeichert.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const aufgaben = [\n  { titel: &quot;Grundlagen lernen&quot;, erledigt: true },\n  { titel: &quot;Array-Methoden üben&quot;, erledigt: false }\n];\nconst offen = aufgaben.filter(a =&gt; !a.erledigt);\nconsole.log(offen.map(a =&gt; a.titel));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">[&quot;Array-Methoden üben&quot;]</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Ergänze eine dritte Aufgabe und gib nur die offenen Aufgaben aus.</div>"},{"title":"Projekt: Quiz-Anwendung","short":"Projekt Quiz","desc":"Baue die Logik eines Quiz mit Fragen, Antworten und Punktestand.","goals":["Du strukturierst Fragen in Objekten","Du vergleichst Antworten","Du berechnest eine Punktzahl"],"section":"Fragen und Auswertung modellieren","body":"Ein Quiz lässt sich mit einem Array aus Frageobjekten modellieren. Jedes Objekt enthält eine Frage, Antwortmöglichkeiten und den Index der richtigen Antwort. Die Auswertung zählt korrekte Antworten und kann daraus einen Prozentwert berechnen.","example":"const fragen = [\n  { frage: \"2 + 2?\", antworten: [3, 4, 5], richtig: 1 },\n  { frage: \"JavaScript-Typ für true?\", antworten: [\"String\", \"Boolean\"], richtig: 1 }\n];\nconst nutzerAntworten = [1, 0];\nconst punkte = fragen.filter((f, i) => f.richtig === nutzerAntworten[i]).length;\nconsole.log(`Punkte: ${punkte} von ${fragen.length}`);","expected":"Punkte: 1 von 2","task":"Füge eine Frage hinzu und passe nutzerAntworten so an, dass alle Antworten richtig sind.","quiz":{"q":"Wie berechnet man die Trefferquote in Prozent?","opts":["Punkte / Fragen * 100","Fragen - Punkte","Punkte + Fragen"],"correct":0,"explain":"Die Quote ist die Anzahl richtiger Antworten geteilt durch die Gesamtzahl, multipliziert mit 100."},"explanation":"<p>Ein Quiz lässt sich mit einem Array aus Frageobjekten modellieren. Jedes Objekt enthält eine Frage, Antwortmöglichkeiten und den Index der richtigen Antwort. Die Auswertung zählt korrekte Antworten und kann daraus einen Prozentwert berechnen.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const fragen = [\n  { frage: &quot;2 + 2?&quot;, antworten: [3, 4, 5], richtig: 1 },\n  { frage: &quot;JavaScript-Typ für true?&quot;, antworten: [&quot;String&quot;, &quot;Boolean&quot;], richtig: 1 }\n];\nconst nutzerAntworten = [1, 0];\nconst punkte = fragen.filter((f, i) =&gt; f.richtig === nutzerAntworten[i]).length;\nconsole.log(`Punkte: ${punkte} von ${fragen.length}`);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Punkte: 1 von 2</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Füge eine Frage hinzu und passe nutzerAntworten so an, dass alle Antworten richtig sind.</div>"},{"title":"Projekt: Ausgaben-Tracker","short":"Projekt Finanzen","desc":"Berechne Summen und filtere Ausgaben nach Kategorien.","goals":["Du speicherst Transaktionen als Objekte","Du summierst Beträge","Du filterst nach Kategorien"],"section":"Daten erfassen und auswerten","body":"Ein Ausgaben-Tracker speichert Transaktionen mit Beschreibung, Kategorie und Betrag. Array-Methoden helfen, Kategorien zu filtern und Summen zu berechnen. In einer echten Anwendung solltest du Beträge für exakte Geldberechnungen häufig in Cent als ganze Zahlen speichern.","example":"const transaktionen = [\n  { text: \"Brot\", kategorie: \"Essen\", cent: 350 },\n  { text: \"Bus\", kategorie: \"Transport\", cent: 290 },\n  { text: \"Obst\", kategorie: \"Essen\", cent: 420 }\n];\nconst essen = transaktionen.filter(t => t.kategorie === \"Essen\");\nconst summeCent = essen.reduce((summe, t) => summe + t.cent, 0);\nconsole.log(\"Essen gesamt:\", (summeCent / 100).toFixed(2), \"Euro\");","expected":"Essen gesamt: 7.70 Euro","task":"Füge eine weitere Essen-Transaktion hinzu und berechne die neue Summe.","quiz":{"q":"Warum kann es sinnvoll sein, Geldbeträge in Cent zu speichern?","opts":["Weil ganze Zahlen Geldberechnungen oft robuster machen","Weil JavaScript keine Dezimalzahlen kennt","Damit Arrays schneller heißen"],"correct":0,"explain":"Binäre Gleitkommazahlen können Rundungsartefakte erzeugen; ganze Cent-Beträge vermeiden viele solcher Probleme."},"explanation":"<p>Ein Ausgaben-Tracker speichert Transaktionen mit Beschreibung, Kategorie und Betrag. Array-Methoden helfen, Kategorien zu filtern und Summen zu berechnen. In einer echten Anwendung solltest du Beträge für exakte Geldberechnungen häufig in Cent als ganze Zahlen speichern.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const transaktionen = [\n  { text: &quot;Brot&quot;, kategorie: &quot;Essen&quot;, cent: 350 },\n  { text: &quot;Bus&quot;, kategorie: &quot;Transport&quot;, cent: 290 },\n  { text: &quot;Obst&quot;, kategorie: &quot;Essen&quot;, cent: 420 }\n];\nconst essen = transaktionen.filter(t =&gt; t.kategorie === &quot;Essen&quot;);\nconst summeCent = essen.reduce((summe, t) =&gt; summe + t.cent, 0);\nconsole.log(&quot;Essen gesamt:&quot;, (summeCent / 100).toFixed(2), &quot;Euro&quot;);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Essen gesamt: 7.70 Euro</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Füge eine weitere Essen-Transaktion hinzu und berechne die neue Summe.</div>"},{"title":"Projekt: Wetter-App vorbereiten","short":"Projekt Wetter & API","desc":"Plane eine Wetter-App und verstehe die Schritte eines API-Aufrufs.","goals":["Du kennst den Ablauf eines API-Requests","Du planst Lade- und Fehlerzustände","Du weißt, dass ein API-Zugang nötig sein kann"],"section":"Vom API-Aufruf zur Anzeige","body":"Eine Wetter-App braucht einen Wetterdienst, einen Standort oder eine Stadteingabe und eine API-Anfrage. Die Oberfläche sollte Ladezustand, erfolgreiche Daten und Fehler unterscheiden. Manche Dienste verlangen einen API-Schlüssel; dieser sollte nicht als Geheimnis in einer öffentlich verteilten Frontend-Datei betrachtet werden. Dieses Beispiel simuliert eine Antwort, damit es offline ausführbar bleibt.","example":"async function wetterLaden() {\n  console.log(\"Wetter wird geladen …\");\n  const antwort = { stadt: \"Berlin\", temperatur: 18, einheit: \"°C\" };\n  console.log(`${antwort.stadt}: ${antwort.temperatur}${antwort.einheit}`);\n}\nwetterLaden();","expected":"Wetter wird geladen …\nBerlin: 18°C","task":"Ergänze ein Feld beschreibung und gib beispielsweise \"Leicht bewölkt\" aus.","quiz":{"q":"Welche Zustände sollte eine robuste API-Oberfläche mindestens unterscheiden?","opts":["Laden, Erfolg und Fehler","Nur Erfolg","Nur einen leeren Bildschirm"],"correct":0,"explain":"Lade-, Erfolgs- und Fehlerzustände machen die Oberfläche verständlich."},"explanation":"<p>Eine Wetter-App braucht einen Wetterdienst, einen Standort oder eine Stadteingabe und eine API-Anfrage. Die Oberfläche sollte Ladezustand, erfolgreiche Daten und Fehler unterscheiden. Manche Dienste verlangen einen API-Schlüssel; dieser sollte nicht als Geheimnis in einer öffentlich verteilten Frontend-Datei betrachtet werden. Dieses Beispiel simuliert eine Antwort, damit es offline ausführbar bleibt.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">async function wetterLaden() {\n  console.log(&quot;Wetter wird geladen …&quot;);\n  const antwort = { stadt: &quot;Berlin&quot;, temperatur: 18, einheit: &quot;°C&quot; };\n  console.log(`${antwort.stadt}: ${antwort.temperatur}${antwort.einheit}`);\n}\nwetterLaden();</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Wetter wird geladen …\nBerlin: 18°C</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Ergänze ein Feld beschreibung und gib beispielsweise \"Leicht bewölkt\" aus.</div>"},{"title":"Abschlussprojekt: Eigene Web-App","short":"Abschlussprojekt","desc":"Plane, entwickle und prüfe eine kleine Anwendung eigenständig.","goals":["Du definierst Anforderungen","Du strukturierst Daten und Funktionen","Du testest und dokumentierst deine Lösung"],"section":"Vom Problem zum fertigen Projekt","body":"Wähle ein überschaubares Problem, schreibe drei bis fünf Anforderungen auf und skizziere die Datenstruktur. Entwickle zuerst die Kernlogik, dann die Benutzeroberfläche, anschließend Speicherung und Fehlerbehandlung. Teste Normalfälle und Grenzfälle und dokumentiere, wie die Anwendung gestartet wird.","example":"const projekt = {\n  name: \"Meine Lernliste\",\n  funktionen: [\"Eintrag hinzufügen\", \"Eintrag abhaken\", \"Eintrag löschen\"],\n  fertig: false\n};\nconsole.log(projekt.name);\nconsole.log(\"Anforderungen:\", projekt.funktionen.length);","expected":"Meine Lernliste\nAnforderungen: 3","task":"Definiere eine eigene Anwendung und notiere drei Anforderungen, eine Datenstruktur und zwei Tests.","quiz":{"q":"Was sollte vor dem Programmieren klar sein?","opts":["Das Problem und die Anforderungen","Die Farbe jedes Icons","Der gesamte Code auswendig"],"correct":0,"explain":"Klare Anforderungen helfen, den Umfang zu begrenzen und gezielt zu testen."},"explanation":"<p>Wähle ein überschaubares Problem, schreibe drei bis fünf Anforderungen auf und skizziere die Datenstruktur. Entwickle zuerst die Kernlogik, dann die Benutzeroberfläche, anschließend Speicherung und Fehlerbehandlung. Teste Normalfälle und Grenzfälle und dokumentiere, wie die Anwendung gestartet wird.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const projekt = {\n  name: &quot;Meine Lernliste&quot;,\n  funktionen: [&quot;Eintrag hinzufügen&quot;, &quot;Eintrag abhaken&quot;, &quot;Eintrag löschen&quot;],\n  fertig: false\n};\nconsole.log(projekt.name);\nconsole.log(&quot;Anforderungen:&quot;, projekt.funktionen.length);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Meine Lernliste\nAnforderungen: 3</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Definiere eine eigene Anwendung und notiere drei Anforderungen, eine Datenstruktur und zwei Tests.</div>"},{"title":"JavaScript-Spickzettel","short":"Spickzettel","desc":"Wiederhole wichtige Syntax, Methoden und Muster an einem Ort.","goals":["Du erkennst zentrale Syntaxformen","Du kannst häufige Methoden nachschlagen","Du findest ein Muster für neue Aufgaben"],"section":"Kurzreferenz für den Alltag","body":"Variablen: const und let. Bedingungen: if/else. Funktionen: function oder Arrow Function. Arrays: map, filter, find, reduce. Objekte: Punktnotation. Fehler: try/catch. JSON: stringify/parse. Asynchron: async/await. DOM: querySelector, textContent, addEventListener. Nutze die Referenz als Gedächtnisstütze, nicht als Ersatz für das Verstehen.","example":"const zahlen = [2, 4, 6];\nconst verdoppelt = zahlen.map(n => n * 2);\nconst gerade = verdoppelt.filter(n => n % 2 === 0);\nconsole.log(gerade);","expected":"[4,8,12]","task":"Wähle eine Methode aus dem Spickzettel und schreibe ein eigenes Beispiel dazu.","quiz":{"q":"Welche Methode fasst ein Array zu einem Einzelwert zusammen?","opts":["map()","reduce()","filter()"],"correct":1,"explain":"reduce() verarbeitet Array-Elemente zu einem Akkumulator-Ergebnis."},"explanation":"<p>Variablen: const und let. Bedingungen: if/else. Funktionen: function oder Arrow Function. Arrays: map, filter, find, reduce. Objekte: Punktnotation. Fehler: try/catch. JSON: stringify/parse. Asynchron: async/await. DOM: querySelector, textContent, addEventListener. Nutze die Referenz als Gedächtnisstütze, nicht als Ersatz für das Verstehen.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const zahlen = [2, 4, 6];\nconst verdoppelt = zahlen.map(n =&gt; n * 2);\nconst gerade = verdoppelt.filter(n =&gt; n % 2 === 0);\nconsole.log(gerade);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">[4,8,12]</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Wähle eine Methode aus dem Spickzettel und schreibe ein eigenes Beispiel dazu.</div>"},{"title":"Glossar wichtiger Begriffe","short":"Glossar","desc":"Lerne zentrale Begriffe aus der JavaScript-Entwicklung kennen.","goals":["Du erklärst Scope und Callback","Du kennst API und Promise","Du kannst DOM und JSON einordnen"],"section":"Fachsprache verstehen","body":"Scope ist der Gültigkeitsbereich einer Variable. Ein Callback ist eine Funktion, die einer anderen Funktion übergeben wird. Ein Promise repräsentiert ein zukünftiges Ergebnis. Eine API ist eine definierte Schnittstelle. Das DOM bildet eine HTML-Seite als Objektstruktur ab. JSON ist ein Textformat für strukturierte Daten. Ein Debugger hilft, die Ausführung schrittweise zu untersuchen.","example":"const begriffe = {\n  Scope: \"Gültigkeitsbereich\",\n  Callback: \"Übergebene Funktion\",\n  Promise: \"Zukünftiges Ergebnis\",\n  DOM: \"Objektmodell der Webseite\"\n};\nconsole.log(begriffe.Scope);\nconsole.log(begriffe.Promise);","expected":"Gültigkeitsbereich\nZukünftiges Ergebnis","task":"Ergänze das Glossar um die Begriffe API und JSON mit eigenen Erklärungen.","quiz":{"q":"Was beschreibt der Scope?","opts":["Den Gültigkeitsbereich von Variablen","Die Farbe einer Webseite","Den Dateinamen"],"correct":0,"explain":"Scope beschreibt, wo ein Name im Programm zugänglich ist."},"explanation":"<p>Scope ist der Gültigkeitsbereich einer Variable. Ein Callback ist eine Funktion, die einer anderen Funktion übergeben wird. Ein Promise repräsentiert ein zukünftiges Ergebnis. Eine API ist eine definierte Schnittstelle. Das DOM bildet eine HTML-Seite als Objektstruktur ab. JSON ist ein Textformat für strukturierte Daten. Ein Debugger hilft, die Ausführung schrittweise zu untersuchen.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const begriffe = {\n  Scope: &quot;Gültigkeitsbereich&quot;,\n  Callback: &quot;Übergebene Funktion&quot;,\n  Promise: &quot;Zukünftiges Ergebnis&quot;,\n  DOM: &quot;Objektmodell der Webseite&quot;\n};\nconsole.log(begriffe.Scope);\nconsole.log(begriffe.Promise);</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">Gültigkeitsbereich\nZukünftiges Ergebnis</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Ergänze das Glossar um die Begriffe API und JSON mit eigenen Erklärungen.</div>"},{"title":"Wiederholung & Lernplan","short":"Wiederholen und weiterlernen","desc":"Festige Grundlagen und plane die nächsten Schritte.","goals":["Du erkennst deine Wissenslücken","Du wiederholst schwierige Themen","Du planst ein eigenes Lernziel"],"section":"Wissen dauerhaft festigen","body":"Lerne in kurzen Einheiten und schreibe Code selbst, statt Beispiele nur zu lesen. Wiederhole schwierige Themen nach einigen Tagen. Erkläre Konzepte mit eigenen Worten und baue Projekte ohne Schritt-für-Schritt-Vorlage nach. Ein Fehler ist ein Hinweis darauf, was du als Nächstes untersuchen kannst.","example":"const lernplan = [\"Grundlagen wiederholen\", \"Array-Methoden üben\", \"Ein Mini-Projekt bauen\"];\nlernplan.forEach((schritt, index) => console.log(`${index + 1}. ${schritt}`));","expected":"1. Grundlagen wiederholen\n2. Array-Methoden üben\n3. Ein Mini-Projekt bauen","task":"Lege einen Lernplan mit drei Themen an, die du noch sicherer beherrschen möchtest.","quiz":{"q":"Was unterstützt nachhaltiges Lernen am besten?","opts":["Nur fertigen Code lesen","Selbst schreiben, testen und wiederholen","Fehler vermeiden, indem man nichts ausprobiert"],"correct":1,"explain":"Aktives Üben und Wiederholen hilft, Wissen langfristig zu festigen."},"explanation":"<p>Lerne in kurzen Einheiten und schreibe Code selbst, statt Beispiele nur zu lesen. Wiederhole schwierige Themen nach einigen Tagen. Erkläre Konzepte mit eigenen Worten und baue Projekte ohne Schritt-für-Schritt-Vorlage nach. Ein Fehler ist ein Hinweis darauf, was du als Nächstes untersuchen kannst.</p><h2>Beispiel zum Ausprobieren</h2><p>Sieh dir das Beispiel an, tippe es selbst in den Editor und führe es aus. Danach kannst du Werte ändern und die Ausgabe vergleichen.</p><pre class=\"code-sample\" style=\"white-space:pre-wrap;overflow:auto;background:#1e1e1e;color:#e6edf3;border:1px solid #303744;border-radius:12px;padding:18px 20px;font:14px/1.65 Consolas,'Courier New',monospace\">const lernplan = [&quot;Grundlagen wiederholen&quot;, &quot;Array-Methoden üben&quot;, &quot;Ein Mini-Projekt bauen&quot;];\nlernplan.forEach((schritt, index) =&gt; console.log(`${index + 1}. ${schritt}`));</pre><div class=\"info\"><strong>Erwartete Ausgabe:</strong><pre style=\"white-space:pre-wrap;margin:8px 0 0\">1. Grundlagen wiederholen\n2. Array-Methoden üben\n3. Ein Mini-Projekt bauen</pre></div><div class=\"guide-step\"><strong>Deine Aufgabe</strong>Lege einen Lernplan mit drei Themen an, die du noch sicherer beherrschen möchtest.</div>"}];

// Erweiterter Lernpfad: Die ursprünglichen Lektionen bleiben erhalten.
lessons.push(...advancedLessons.map(({explanation, ...lesson}) => lesson));
explanations.push(...advancedLessons.map(lesson => lesson.explanation));

const STORAGE_KEY="js-academy-local-v1";
console.assert(lessons.length===explanations.length,"⚠ lessons und explanations haben unterschiedliche Längen: "+lessons.length+" vs "+explanations.length);
let state={current:0,completed:[],quizCorrect:[],goals:{},dark:false};
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||"null");if(saved)state={...state,...saved};}catch(e){}
const $=id=>document.getElementById(id);
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function renderNav(){ $("lessonNav").innerHTML=lessons.map((l,i)=>`<button class="nav-item ${i===state.current?"active":""} ${state.completed.includes(i)?"done":""}" data-lesson="${i}"><span class="nav-num">${state.completed.includes(i)?"✓":i+1}</span><span>${esc(l.short)}</span></button>`).join("");}
function renderProgress(){const n=state.completed.length,p=Math.round(n/lessons.length*100);$("progressText").textContent=`Fortschritt: ${n} von ${lessons.length} Lektionen`; $("progressPercent").textContent=p+"%";$("progressFill").style.width=p+"%";$("progressRing").style.setProperty("--pct",p+"%");$("ringText").textContent=p+"%";$("doneCount").textContent=`${n} von ${lessons.length} Lektionen abgeschlossen`;$("quizCount").textContent=`${state.quizCorrect.length} Quizfragen richtig`; }
function render(){
 state.current=Math.max(0,Math.min(lessons.length-1,state.current));const l=lessons[state.current],done=state.completed.includes(state.current),correct=state.quizCorrect.includes(state.current);renderNav();renderProgress();
 $("goals").innerHTML=l.goals.map(g=>`<div class="goal-text"><span class="goal-dot">•</span><span>${esc(g)}</span></div>`).join("");
 $("lessonMain").innerHTML=`<span class="badge">Schritt ${state.current+1} · ${done?"Abgeschlossen":"Lektion"}</span><h1 class="h1">${esc(l.title==="Einführung & Setup"?"JavaScript verstehen und einrichten":l.title)}</h1><p class="lead">${esc(l.desc)}</p><div class="content lesson-explain" id="lessonContent"><h2>${esc(l.section)}</h2>${explanations[state.current]}<div class="info"><strong>Jetzt selbst ausprobieren:</strong> Der Editor ist absichtlich leer. Nutze die Anleitung direkt darüber und tippe den Code selbst ein. So lernst du durch aktives Ausprobieren.</div><h2>Dein JavaScript-Editor</h2><p>Schreibe deinen Code links. Mit „Code ausführen“ wird er gestartet; die Ausgabe und Fehlermeldungen erscheinen rechts. Tastenkürzel: <span class="code-inline">Tab</span> rückt ein, <span class="code-inline">Strg+Enter</span> führt aus.</p><div class="code-area"><div class="code-box"><div class="code-head"><span>JAVASCRIPT ACADEMY · WORKBENCH</span><div class="editor-toolbar"><button class="primary" id="runCode" type="button">▶ Code ausführen</button><button class="small-btn" id="copyCode" type="button">Kopieren</button><button class="small-btn" id="clearCode" type="button">Leeren</button></div></div><div class="editor-column" style="width:100%"><div class="file-tabs" id="fileTabs"><button type="button" class="file-tab active" data-file="main.js">JS&nbsp; main.js</button><button type="button" class="file-tab" data-file="index.html">HTML&nbsp; index.html</button><button type="button" class="file-tab" data-file="style.css">CSS&nbsp; style.css</button><span id="fileTypeLabel" style="margin-left:auto;padding:0 10px;color:#7f8ea3;font-size:11px">JavaScript</span></div><div class="editor-shell"><div class="line-numbers" id="lineNumbers">1</div><div class="editor-stack"><pre class="code-highlight" id="codeHighlight" aria-hidden="true"></pre><textarea id="codeInput" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" aria-label="JavaScript-Code-Editor" placeholder="// Schreibe hier deinen JavaScript-Code …"></textarea><div id="suggestions" class="suggestions" hidden></div></div></div><div class="editor-help">JavaScript · UTF-8 · Tab: Einrückung · Strg+Enter: Ausführen · Strg+Leertaste: Vorschläge · Strg+F: Suchen</div><div class="editor-status"><span id="editorPosition">Zeile 1, Spalte 1</span><span id="editorCount">0 Zeichen</span></div><div class="workbench-tools"><button id="findCode">⌕ Suchen/Ersetzen</button><button id="checkCode">✓ Code prüfen</button><button id="explainCode">? Auswahl erklären</button><button id="downloadFile">↓ Datei exportieren</button><button id="downloadProject">↓ Projektdateien</button></div><div class="search-replace" id="searchReplace" hidden><input id="findText" placeholder="Suchen…"><input id="replaceText" placeholder="Ersetzen durch…"><button id="findNext">Nächstes</button><button id="replaceOne">Ersetzen</button><button id="replaceAll">Alle ersetzen</button><button id="closeSearch">Schließen</button></div><div id="problems" class="problem-panel"></div></div></div><div class="output-box"><div class="code-head"><span>Ausgabe</span><span id="runStatus">Bereit</span></div><div class="output" id="output">Deine Ausgabe erscheint hier, sobald du den Code ausführst.</div><div class="editor-help">Tipp: console.log("Hallo!") zeigt Text hier an.</div><div class="console-input"><input id="consoleCommand" type="text" aria-label="Konsolenbefehl" placeholder="> Ausdruck testen, z. B. 2 + 2"><button type="button" id="sendConsole">Ausführen</button></div></div></div><div class="task"><h3>Deine Aufgabe</h3><p>${esc(l.task)}</p><p class="muted">Arbeite direkt im Editor. Ändere deinen Code und führe ihn erneut aus.</p></div><div class="task"><h3>Wissenscheck</h3><p>${esc(l.quiz.q)}</p><div class="answer-list">${l.quiz.opts.map((o,i)=>`<button class="answer" data-answer="${i}" ${correct?"disabled":""}>${String.fromCharCode(65+i)} · ${esc(o)}</button>`).join("")}</div><div id="quizFeedback" class="feedback" aria-live="polite">${correct?"✓ Diese Quizfrage hast du bereits richtig beantwortet.":""}</div></div><div class="action-row" style="margin-top:18px"><button class="primary" id="markDone">${done?"✓ Lektion abgeschlossen":"Lektion als abgeschlossen markieren"}</button></div></div><div class="lesson-footer"><button class="secondary" id="prevLesson" ${state.current===0?"disabled":""}>← Vorherige Lektion</button><button class="primary" id="nextLesson">${state.current===lessons.length-1?"Zum Anfang zurück":"Nächste Lektion →"}</button></div>`;
 const editor=$("codeInput");activeFile="main.js";fileBuffers={"main.js":"","index.html":"<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<title>Mein Projekt</title>\n</head>\n<body>\n  <h1>Hallo Welt!</h1>\n</body>\n</html>","style.css":"body {\n  font-family: system-ui, sans-serif;\n  padding: 2rem;\n}\nh1 { color: royalblue; }"};try{editor.value=localStorage.getItem("js-academy-draft-"+state.current)||"";for(const f of Object.keys(fileBuffers)){const saved=localStorage.getItem("js-academy-file-"+state.current+"-"+f);if(saved!==null)fileBuffers[f]=saved;}}catch(e){editor.value="";}fileBuffers["main.js"]=editor.value;try{const names=JSON.parse(localStorage.getItem("js-academy-files-"+state.current)||"[]");for(const n of names){if(!(n in fileBuffers)){const saved=localStorage.getItem("js-academy-file-"+state.current+"-"+n);if(saved!==null)fileBuffers[n]=saved;}}}catch(e){}document.querySelectorAll("[data-file]").forEach(b=>b.addEventListener("click",()=>switchFile(b.dataset.file)));updateEditor();editor.addEventListener("input",()=>{updateEditor();if(editor.value.slice(Math.max(0,editor.selectionStart-1),editor.selectionStart).match(/[A-Za-z_$]/))showSuggestions(true);});editor.addEventListener("scroll",()=>{$("lineNumbers").scrollTop=editor.scrollTop;$("codeHighlight").scrollTop=editor.scrollTop;$("codeHighlight").scrollLeft=editor.scrollLeft;});editor.addEventListener("keyup",updateEditor);editor.addEventListener("click",updateEditor);editor.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.code==="Space"){e.preventDefault();showSuggestions();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();saveCurrentFile();$("runStatus").textContent="Lokal gespeichert";return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="f"){e.preventDefault();$("searchReplace").hidden=false;$("findText").focus();return;}if(e.key==="Tab"){e.preventDefault();editor.setRangeText("  ",editor.selectionStart,editor.selectionEnd,"end");updateEditor();return;}if(e.key==="Enter"&&(e.ctrlKey||e.metaKey)){e.preventDefault();runUserCode();return;}const pairs={"(":")","[":"]","{":"}","\"":"\"","\'":"\'","`":"`"};if(pairs[e.key]&&editor.selectionStart===editor.selectionEnd){e.preventDefault();const pos=editor.selectionStart;editor.setRangeText(e.key+pairs[e.key],pos,pos,"end");editor.selectionStart=editor.selectionEnd=pos+1;updateEditor();return;}if(e.key==="Escape")$("suggestions").hidden=true;});$("suggestions").addEventListener("click",e=>{const b=e.target.closest("[data-completion]");if(b)insertCompletion(completions[Number(b.dataset.completion)]);});
 const onEl=(id,event,handler)=>{const el=$(id);if(el)el.addEventListener(event,handler);};
 onEl("runCode","click",runUserCode);onEl("sendConsole","click",runConsoleCommand);onEl("consoleCommand","keydown",e=>{if(e.key==="Enter")runConsoleCommand();});onEl("clearCode","click",()=>{editor.value="";updateEditor();editor.focus();if($("output"))$("output").textContent="Editor geleert. Schreibe Code und führe ihn aus.";});onEl("copyCode","click",async()=>{try{await navigator.clipboard.writeText(editor.value);$("copyCode").textContent="Kopiert!";setTimeout(()=>$("copyCode").textContent="Kopieren",1200);}catch(e){$("copyCode").textContent="Bitte manuell markieren";}});onEl("formatCode","click",formatCurrentCode);
 $("markDone").addEventListener("click",()=>{if(!state.completed.includes(state.current))state.completed.push(state.current);persist();render();});$("prevLesson").addEventListener("click",()=>go(state.current-1));$("nextLesson").addEventListener("click",()=>go((state.current+1)%lessons.length));document.querySelectorAll("[data-answer]").forEach(b=>b.addEventListener("click",()=>answerQuiz(Number(b.dataset.answer))));bindWorkbench();renderFileLists();
}
function highlightCode(code){const tokens=/(\/\*[\s\S]*?\*\/|\/\/[^\n]*|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`|\b(?:const|let|var|function|return|if|else|for|while|do|switch|case|break|continue|new|class|extends|try|catch|throw|typeof|instanceof|import|export|from|async|await|this|in|of)\b|\b(?:true|false|null|undefined|NaN)\b|\b\d+(?:\.\d+)?\b|\b[A-Za-z_$][\w$]*(?=\s*\()|\bconsole\b)/g;let out="",last=0,m;while((m=tokens.exec(code))){out+=esc(code.slice(last,m.index));const t=m[0];let cls="";if(t.startsWith("//")||t.startsWith("/*"))cls="com";else if(/["\'`]/.test(t[0]))cls="str";else if(/^\d/.test(t))cls="num";else if(/^(true|false|null|undefined|NaN)$/.test(t))cls="bool";else if(/^(const|let|var|function|return|if|else|for|while|do|switch|case|break|continue|new|class|extends|try|catch|throw|typeof|instanceof|import|export|from|async|await|this|in|of)$/.test(t))cls="kw";else cls="fn";out+=`<span class="${cls}">${esc(t)}</span>`;last=tokens.lastIndex;}out+=esc(code.slice(last));return out+ (code.endsWith("\n")?" ":"");}
const completions=["console.log()","const ","let ","function ","if () {\n  \n}","for (let i = 0; i <  ; i++) {\n  \n}","true","false","Math.random()","Array","String","Number","return ","document.querySelector()"];
function showSuggestions(auto=false){const box=$("suggestions"),e=$("codeInput");if(!box||!e)return;const prefix=(e.value.slice(0,e.selectionStart).match(/[A-Za-z_$][\w$]*$/)||[""])[0];const list=auto&&prefix?completions.filter(x=>x.toLowerCase().startsWith(prefix.toLowerCase())):completions;box.innerHTML=list.map(x=>{const i=completions.indexOf(x);return `<button type="button" data-completion="${i}">${esc(x.replace(/\n/g,"↵"))}</button>`}).join("");box.hidden=!list.length;}
function insertCompletion(value){const e=$("codeInput");let start=e.selectionStart,end=e.selectionEnd;const prefix=(e.value.slice(0,start).match(/[A-Za-z_$][\w$]*$/)||[""])[0];if(prefix){start-=prefix.length;}e.setRangeText(value,start,end,"end");$("suggestions").hidden=true;updateEditor();e.focus();}
let activeFile="main.js",fileBuffers={};
function saveCurrentFile(){const input=$("codeInput");if(!activeFile||!input)return;fileBuffers[activeFile]=input.value;try{localStorage.setItem("js-academy-file-"+state.current+"-"+activeFile,fileBuffers[activeFile]);localStorage.setItem("js-academy-files-"+state.current,JSON.stringify(Object.keys(fileBuffers)));}catch(e){}}
function renderFileLists(){
 const names=Object.keys(fileBuffers);
 const icon=n=>n.endsWith(".js")?"🟨":n.endsWith(".html")?"🟠":n.endsWith(".css")?"🔵":"📄";
 const label=n=>n.endsWith(".js")?"JavaScript":n.endsWith(".html")?"HTML":n.endsWith(".css")?"CSS":"Text";
 const explorer=$("explorerFiles");
 // Der Datei-Explorer ist optional. Die Tabs müssen auch ohne ihn funktionieren.
 if(explorer) explorer.innerHTML=names.map(n=>`<button type="button" class="explorer-file ${n===activeFile?"active":""}" data-file="${esc(n)}">${icon(n)} ${esc(n)}</button>`).join("");
 const tabs=$("fileTabs");
 if(tabs){
   tabs.innerHTML=names.map(n=>`<button type="button" class="file-tab ${n===activeFile?"active":""}" data-file="${esc(n)}" aria-pressed="${n===activeFile}">${icon(n)} ${esc(n)}</button>`).join("")+`<span id="fileTypeLabel" style="margin-left:auto;padding:0 10px;color:#7f8ea3;font-size:11px">${label(activeFile)}</span>`;
   // Event-Delegation bleibt auch nach dem Neurendern der Tabs erhalten.
   tabs.onclick=e=>{const b=e.target.closest("[data-file]");if(b)switchFile(b.dataset.file);};
 }
 if(explorer) explorer.onclick=e=>{const b=e.target.closest("[data-file]");if(b)switchFile(b.dataset.file);};
 const editor=$("codeInput");
 if(editor) editor.placeholder=activeFile.endsWith(".js")?"// Schreibe hier deinen JavaScript-Code …":activeFile.endsWith(".html")?"<!-- Schreibe hier dein HTML … -->":activeFile.endsWith(".css")?"/* Schreibe hier dein CSS … */":"Schreibe hier deinen Code …";
 const run=$("runCode");if(run)run.textContent=activeFile.endsWith(".js")?"▶ Projekt ausführen":"▶ Vorschau ausführen";
}
function switchFile(name, force){
 if(!(name in fileBuffers)||(!force && name===activeFile))return;
 if(name!==activeFile) saveCurrentFile();
 activeFile=name;
 const e=$("codeInput");
 if(!e)return;
 e.value=fileBuffers[name]||"";
 renderFileLists();
 updateEditor();
 e.focus();
}
function updateEditor(){const e=$("codeInput");if(!e)return;const lines=e.value.split("\n");fileBuffers[activeFile]=e.value;try{localStorage.setItem("js-academy-file-"+state.current+"-"+activeFile,e.value);}catch(err){}const ln=$("lineNumbers"),hl=$("codeHighlight");if(ln){ln.textContent=lines.map((_,i)=>i+1).join("\n");ln.scrollTop=e.scrollTop;}if(hl){hl.innerHTML=highlightCode(e.value);hl.scrollTop=e.scrollTop;hl.scrollLeft=e.scrollLeft;}const before=e.value.slice(0,e.selectionStart).split("\n");if($("editorPosition"))$("editorPosition").textContent=`Zeile ${before.length}, Spalte ${before[before.length-1].length+1}`;if($("editorCount"))$("editorCount").textContent=`${e.value.length} Zeichen`;try{localStorage.setItem("js-academy-draft-"+state.current,e.value);}catch(err){}}

function runUserCode(){
 saveCurrentFile();const out=$("output"),logs=[];if(!out)return;const js=fileBuffers["main.js"]||"",html=fileBuffers["index.html"]||"<!doctype html><html><head><meta charset=\"utf-8\"></head><body></body></html>",css=fileBuffers["style.css"]||"";
 const problems=$("problems");const activeExt=activeFile.split(".").pop();if(activeExt==="js"){
   try{new Function(js);if(problems){problems.textContent="✓ Keine offensichtlichen Syntaxfehler in main.js gefunden.";problems.className="problem-panel";}}catch(e){const line=(e.stack||"").match(/<anonymous>:(\d+):/)?.[1]||"unbekannt";if(problems)problems.innerHTML='<span class="problem-error">✖ '+esc(e.name+": "+e.message+" (Zeile "+line+")")+'</span>';out.textContent="Syntaxfehler: "+e.message;if($("runStatus"))$("runStatus").textContent="Fehler";return;}
 }
 const instrument="<script>const send=(type,args)=>parent.postMessage({source:'js-academy-preview',type,args:args.map(v=>{try{return typeof v==='string'?v:JSON.stringify(v)}catch(e){return String(v)}})},'*');console.log=(...a)=>send('log',a);console.warn=(...a)=>send('warn',a);console.error=(...a)=>send('error',a);window.onerror=(m,src,line,col)=>send('error',[m+' (Zeile '+line+')']);<\/script>";
 let doc=html;
 if(!/<head(?:\s|>)/i.test(doc)){
  if(/<html(?:\s|>)/i.test(doc))doc=doc.replace(/<html([^>]*)>/i,'<html$1><head></head>');
  else doc='<html><head></head><body>'+doc+'</body></html>';
 }
 const safeCss=css.replace(/<\/style/gi,'');
 if(/<head([^>]*)>/i.test(doc))doc=doc.replace(/<head([^>]*)>/i,(_,attrs)=>'<head'+attrs+'><style>'+safeCss+'</style>'+instrument);
 else doc=doc.replace(/<html([^>]*)>/i,(_,attrs)=>'<html'+attrs+'><head><style>'+safeCss+'</style>'+instrument+'</head>');
 if(js.trim()){const sc='<script>'+js.replace(/<\/script/gi,'')+'<\/script>';if(/<\/body>/i.test(doc))doc=doc.replace(/<\/body>/i,sc+'</body>');else doc+=sc;}
  const frame=document.createElement("iframe");frame.setAttribute("sandbox","allow-scripts");frame.title="Vorschau";frame.style.cssText="width:100%;min-height:240px;border:0;background:#fff;display:block";out.replaceChildren(frame);frame.srcdoc=doc;if($("runStatus"))$("runStatus").textContent="Wird ausgeführt …";
  const logBox=document.createElement("pre");logBox.style.cssText="margin:8px 0 0;white-space:pre-wrap;font:12px/1.45 ui-monospace,monospace";out.appendChild(logBox);logBox.textContent="Ausführung gestartet. Konsolenausgaben erscheinen hier.";
  const handler=ev=>{if(!ev.data||ev.data.source!=="js-academy-preview")return;const line=(ev.data.type==="warn"?"⚠ Warnung: ":ev.data.type==="error"?"✖ Fehler: ":"› ")+(ev.data.args||[]).join(" ");logs.push(line);logBox.textContent=logs.join("\n")||"Keine Ausgabe.";logBox.style.color=ev.data.type==="error"?"#fca5a5":ev.data.type==="warn"?"#fcd34d":"#e5edf7";if($("runStatus"))$("runStatus").textContent=ev.data.type==="error"?"Fehler":"Läuft";};window.addEventListener("message",handler);setTimeout(()=>{window.removeEventListener("message",handler);if(!logs.length){logBox.textContent="Ausgeführt. Keine console.log()-Ausgabe vorhanden.";logBox.style.color="";if($("runStatus"))$("runStatus").textContent="Fertig";}},4000);
}
function runConsoleCommand(){const input=$("consoleCommand"),out=$("output"),value=input.value.trim();if(!value)return;const frame=document.createElement("iframe");frame.sandbox="allow-scripts";frame.style.display="none";document.body.appendChild(frame);const id="console-"+Date.now()+Math.random();const handler=ev=>{if(!ev.data||ev.data.id!==id)return;window.removeEventListener("message",handler);frame.remove();out.textContent+=(out.textContent&&out.textContent!=="Deine Ausgabe erscheint hier, sobald du den Code ausführst."?"\n":"")+"> "+value+"\n"+(ev.data.ok?String(ev.data.value):"Fehler: "+ev.data.error);out.style.color=ev.data.ok?"#e5edf7":"#fca5a5";$("runStatus").textContent=ev.data.ok?"Konsolenausdruck":"Fehler";};window.addEventListener("message",handler);const tag=String.fromCharCode(60)+"script>";const endTag=String.fromCharCode(60)+"/"+"script>";frame.srcdoc=tag+"try{const value=("+value.replace(/<\/script/gi,'')+");parent.postMessage({id:"+JSON.stringify(id)+",ok:true,value:value},'*')}catch(e){parent.postMessage({id:"+JSON.stringify(id)+",ok:false,error:e.message},'*')}"+endTag;input.value="";setTimeout(()=>{window.removeEventListener("message",handler);if(frame.isConnected)frame.remove();},500);}
function checkCurrentCode(){saveCurrentFile();const code=fileBuffers[activeFile]||"",problems=[];if(activeFile.endsWith(".js")){try{new Function(code);}catch(e){let line="?";const m=(e.stack||"").match(/<anonymous>:(\d+):/);if(m)line=m[1];problems.push({kind:"error",text:e.name+": "+e.message+" — Zeile "+line});}const opens=(code.match(/[({[]/g)||[]).length,closes=(code.match(/[)}\]]/g)||[]).length;if(opens!==closes)problems.push({kind:"warn",text:"Anzahl öffnender und schließender Klammern unterscheidet sich. Prüfe Strings/Kommentare ebenfalls."});if(!code.trim())problems.push({kind:"warn",text:"Die Datei ist leer. Tippe JavaScript ein, um sie zu prüfen."});}else if(activeFile.endsWith(".html")&&!/<html|<body|<!doctype/i.test(code))problems.push({kind:"warn",text:"HTML-Datei enthält keine erkennbare HTML-Grundstruktur."});else if(activeFile.endsWith(".css")&&((code.match(/{/g)||[]).length!==(code.match(/}/g)||[]).length))problems.push({kind:"error",text:"CSS: öffnende und schließende geschweifte Klammern stimmen nicht überein."});const panel=$("problems");if(panel)panel.innerHTML=problems.length?problems.map(p=>`<div class="problem-${p.kind}">${p.kind==="error"?"✖":"⚠"} ${esc(p.text)}</div>`).join(""):"✓ Keine offensichtlichen Probleme gefunden.";if($("runStatus"))$("runStatus").textContent=problems.some(p=>p.kind==="error")?"Prüfen: Fehler":"Prüfung fertig";}
function formatCurrentCode(){const e=$("codeInput");let lines=e.value.replace(/\t/g,"  ").split("\n");let depth=0;lines=lines.map(line=>{let t=line.trim();if(!t)return "";if(/^[}\])]/.test(t))depth=Math.max(0,depth-1);const out="  ".repeat(depth)+t;if(/[({[]\s*$/.test(t)&&!/^\/\//.test(t))depth++;return out;});e.value=lines.join("\n");updateEditor();saveCurrentFile();}
function explainSelection(){const e=$("codeInput"),selected=e.value.slice(e.selectionStart,e.selectionEnd).trim()||e.value.split("\n").find(x=>x.trim())||"";let msg="Markiere einen Codeabschnitt oder schreibe zuerst Code.";if(selected){if(/console\.log/.test(selected))msg="console.log(...) gibt Werte in der Konsole aus.";else if(/\b(const|let|var)\b/.test(selected))msg="Diese Zeile deklariert eine Variable. const verhindert eine Neuzuweisung, let erlaubt sie.";else if(/\bfunction\b|=>/.test(selected))msg="Das ist eine Funktion: wiederverwendbarer Code, der bei einem Aufruf ausgeführt wird.";else if(/\bif\b/.test(selected))msg="Eine if-Anweisung führt den eingerückten Block nur aus, wenn die Bedingung wahr ist.";else if(/\b(for|while)\b/.test(selected))msg="Das ist eine Schleife. Sie wiederholt Code, solange ihre Laufbedingung erfüllt ist.";else if(/\/\//.test(selected))msg="Text nach // ist ein Kommentar und wird nicht als JavaScript ausgeführt.";else msg="Lies den Abschnitt von innen nach außen. Achte auf Variablen, Funktionsaufrufe, Klammern und Rückgabewerte.";}alert("Code-Erklärung\n\n"+msg+"\n\nAuswahl:\n"+selected.slice(0,500));}
function downloadBlob(name,content,type="text/plain;charset=utf-8"){const a=document.createElement("a"),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadProjectFiles(){saveCurrentFile();Object.keys(fileBuffers).forEach(n=>downloadBlob(n,fileBuffers[n],n.endsWith(".html")?"text/html;charset=utf-8":n.endsWith(".css")?"text/css;charset=utf-8":"text/javascript;charset=utf-8"));}
function bindWorkbench(){
 const on=(id,event,handler)=>{const el=$(id);if(el)el.addEventListener(event,handler);};
 on("newFile","click",()=>{const name=prompt("Dateiname mit Endung, z. B. app.js:");if(!name)return;const clean=name.trim();if(!/^[\w.-]+$/.test(clean)||!clean.includes(".")){alert("Bitte einen einfachen Dateinamen mit Endung verwenden.");return;}if(clean in fileBuffers){alert("Diese Datei existiert bereits.");return;}saveCurrentFile();fileBuffers[clean]="";switchFile(clean);});
 on("renameFile","click",()=>{const name=prompt("Neuer Dateiname:",activeFile);if(!name||name===activeFile)return;if(!/^[\w.-]+$/.test(name)||!name.includes(".")){alert("Ungültiger Dateiname.");return;}if(name in fileBuffers){alert("Eine Datei mit diesem Namen existiert bereits.");return;}saveCurrentFile();fileBuffers[name]=fileBuffers[activeFile];delete fileBuffers[activeFile];try{localStorage.removeItem("js-academy-file-"+state.current+"-"+activeFile);}catch(e){}switchFile(name,true);});
 on("deleteFile","click",()=>{if(Object.keys(fileBuffers).length<=1){alert("Mindestens eine Datei muss im Projekt bleiben.");return;}if(!confirm(activeFile+" wirklich löschen?"))return;const old=activeFile;delete fileBuffers[old];try{localStorage.removeItem("js-academy-file-"+state.current+"-"+old);}catch(e){}switchFile(Object.keys(fileBuffers)[0],true);});
 on("findCode","click",()=>{const panel=$("searchReplace");if(panel){panel.hidden=!panel.hidden;const input=$("findText");if(input)input.focus();}});
 on("closeSearch","click",()=>{const panel=$("searchReplace");if(panel)panel.hidden=true;});
 on("findNext","click",()=>{const e=$("codeInput"),q=$("findText")?.value;if(!e||!q)return;let at=e.value.indexOf(q,e.selectionEnd);if(at<0)at=e.value.indexOf(q);if(at>=0){e.focus();e.setSelectionRange(at,at+q.length);}});
 on("replaceOne","click",()=>{const e=$("codeInput"),q=$("findText")?.value;if(!e||!q)return;const sel=e.value.slice(e.selectionStart,e.selectionEnd);if(sel===q)e.setRangeText($("replaceText")?.value||"",e.selectionStart,e.selectionEnd,"end");else{const at=e.value.indexOf(q,e.selectionEnd);if(at>=0)e.setRangeText($("replaceText")?.value||"",at,at+q.length,"end");}updateEditor();saveCurrentFile();});
 on("replaceAll","click",()=>{const q=$("findText")?.value;if(!q)return;const e=$("codeInput");if(!e)return;e.value=e.value.split(q).join($("replaceText")?.value||"");updateEditor();saveCurrentFile();});
 on("checkCode","click",checkCurrentCode);on("explainCode","click",explainSelection);
 on("downloadFile","click",()=>{saveCurrentFile();downloadBlob(activeFile,fileBuffers[activeFile]);});
 on("downloadProject","click",downloadProjectFiles);
}
function answerQuiz(i){const l=lessons[state.current],ok=i===l.quiz.correct;document.querySelectorAll("[data-answer]").forEach(b=>{b.disabled=true;const n=Number(b.dataset.answer);if(n===l.quiz.correct)b.classList.add("correct");else if(n===i)b.classList.add("wrong");});const f=$("quizFeedback");f.textContent=(ok?"Richtig! ":"Nicht ganz. ")+l.quiz.explain;f.style.color=ok?"#15803d":"#b91c1c";if(ok&&!state.quizCorrect.includes(state.current))state.quizCorrect.push(state.current);persist();renderProgress();}
function go(i){state.current=Math.max(0,Math.min(lessons.length-1,i));persist();render();window.scrollTo({top:0,behavior:"smooth"});}
$("lessonNav").addEventListener("click",e=>{const b=e.target.closest("[data-lesson]");if(b)go(Number(b.dataset.lesson));});
$("goals").addEventListener("change",e=>{if(e.target.dataset.goal!==undefined){state.goals[state.current+"-"+e.target.dataset.goal]=e.target.checked;persist();}});
$("themeBtn").addEventListener("click",()=>{state.dark=!state.dark;document.body.style.setProperty("--bg",state.dark?"#101722":"#f4f7fb");document.body.style.setProperty("--panel",state.dark?"#1b2635":"#fff");document.body.style.setProperty("--ink",state.dark?"#edf2f8":"#172033");document.body.style.setProperty("--muted",state.dark?"#a9b7ca":"#64748b");document.body.style.setProperty("--line",state.dark?"#354256":"#e3e9f2");document.documentElement.style.setProperty("--ring-inner-bg", state.dark ? "#1b2635" : "white");});
render();

;

(function(){
 if(!state.difficulty||typeof state.difficulty!=="object")state.difficulty={};
 if(!state.reviews||typeof state.reviews!=="object")state.reviews={};
 if(!state.lastOutput||typeof state.lastOutput!=="object")state.lastOutput={lesson:-1,lines:[]};
 let academyComparisonOn=false;
 let academyReviewingLesson=null;

 const academyErrorCatalog=[
  {title:"= statt === in einer Bedingung",symptom:"Der Zweig läuft unerwartet, obwohl du nur vergleichen wolltest.",sample:'if (punkte = 10) { /* ... */ }',fix:'= weist einen Wert zu. Für einen strengen Vergleich von Wert und Typ verwendest du ===.'},
  {title:"Rückgabewert mit return vergessen",symptom:"Die Funktion liefert undefined, obwohl sie etwas berechnet.",sample:'function verdoppeln(n) {\n  n * 2;\n}',fix:'Gib das Ergebnis ausdrücklich zurück: return n * 2;'},
  {title:"const neu zuweisen",symptom:"Beim erneuten Zuweisen erscheint ein TypeError.",sample:'const punkte = 3;\npunkte = 4;',fix:'Verwende let, wenn sich die Bindung ändern soll. const-Objekte und Arrays dürfen intern weiterhin geändert werden.'},
  {title:"== statt ===",symptom:"Werte verschiedener Typen gelten überraschend als gleich.",sample:'console.log(5 == "5");',fix:'=== vergleicht ohne automatische Typumwandlung und ist deshalb meist die klarere Wahl.'},
  {title:"Schleifengrenze um eins verschoben",symptom:"Ein Wert fehlt oder wird ein zusätzliches Mal ausgegeben.",sample:'for (let i = 0; i <= zahlen.length; i++) {\n  console.log(zahlen[i]);\n}',fix:'Bei Array-Indizes endet die Bedingung meist mit i < zahlen.length, weil der letzte Index length - 1 ist.'},
  {title:"Nutzereingabe ungeprüft in innerHTML",symptom:"Text wird als HTML interpretiert und kann unerwartete Elemente erzeugen.",sample:'ausgabe.innerHTML = nutzereingabe;',fix:'Für reinen Text nutze textContent. Wenn HTML nötig ist, muss es sicher validiert oder bereinigt werden.'}
 ];

 function academyToday(){const now=new Date();return new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,10);}
 function academyAddDays(days){const date=new Date();date.setDate(date.getDate()+days);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10);}
 function academyReviews(){return Object.entries(state.reviews).map(([index,review])=>({index:Number(index),review})).filter(item=>Number.isInteger(item.index)&&item.index>=0&&item.index<lessons.length&&item.review&&/^\d{4}-\d{2}-\d{2}$/.test(item.review.due));}
 function academyDueReviews(){const today=academyToday();return academyReviews().filter(item=>item.review.due<=today).sort((a,b)=>a.review.due.localeCompare(b.review.due));}
 function academyChallenge(lesson){const goal=lesson.expected?`Zielausgabe:\n${lesson.expected}`:"Setze das Lernziel der Lektion ohne Beispielcode um.";return `Löse die Aufgabe ohne auf das Beispiel zu schauen. Schreibe eine eigene Lösung und prüfe anschließend, ob sie dieses Ziel erreicht:\n${goal}`;}
 function academyComparisonMarkup(lesson){
  const expected=String(lesson.expected??"").split("\n");
  const saved=state.lastOutput&&state.lastOutput.lesson===state.current?state.lastOutput.lines:[];
  const actual=saved.map(line=>String(line));
  if(!String(lesson.expected??"").trim())return '<p>Für diese Lektion ist keine Referenzausgabe hinterlegt.</p>';
  if(!expected.length)expected.push("");
  const count=Math.max(expected.length,actual.length,1);
  const rows=Array.from({length:count},(_,index)=>{
   const want=expected[index]??"",got=actual[index]??"";
   const match=index<expected.length&&index<actual.length&&want.trim()===got.trim();
   const status=match?"✓":index>=expected.length?"Zusatz":"Abweichung";
   return `<div class="comparison-row ${match?"is-match":"is-mismatch"}"><span>${status}</span><span>${esc(want||"—")}</span><span>${esc(got||"—")}</span></div>`;
  }).join("");
  return `<div class="comparison-grid"><div><h4>Soll</h4><pre class="comparison-output">${esc(String(lesson.expected))}</pre></div><div><h4>Deine letzte Ausgabe</h4><pre class="comparison-output">${esc(actual.length?actual.join("\n"):"Noch keine Ausgabe. Führe deinen Code aus.")}</pre></div></div><div class="comparison-rows" aria-live="polite"><strong>Zeilenvergleich</strong>${rows}</div>`;
 }
 function academyReviewMarkup(){
  const due=academyDueReviews();
  const future=academyReviews().filter(item=>item.review.due>academyToday()).sort((a,b)=>a.review.due.localeCompare(b.review.due));
  const dueHtml=due.length?due.map(({index,review})=>`<button class="review-due-button" type="button" data-academy-review="${index}">${esc(lessons[index].short)} · ${review.due<academyToday()?"überfällig":"heute fällig"}</button>`).join(""):'<div class="review-empty">Heute ist keine Wiederholung fällig. Falsch beantwortete Quizze tauchen hier automatisch wieder auf.</div>';
  const futureHtml=future.length?`<p>Als Nächstes: ${future.slice(0,4).map(({index,review})=>`${esc(lessons[index].short)} (${new Date(review.due+"T00:00:00").toLocaleDateString("de-DE")})`).join(" · ")}</p>`:"";
  return `<section class="learning-feature-section" id="learning-reviews"><div class="learning-feature-heading"><div><h2>Heute wiederholen <span class="review-count">${due.length}</span></h2><p>Falsch beantwortete Quizze werden nach 1, dann 3 und anschließend 7 Tagen erneut angeboten. Eine richtige Antwort entfernt die Wiederholung.</p></div></div><div class="review-list">${dueHtml}</div>${futureHtml}</section>`;
 }
 function academyRenderFeatures(){
  const main=$("lessonMain");if(!main)return;
  const old=$("learningFeaturePanel");if(old)old.remove();
  const lesson=lessons[state.current];if(!lesson)return;
  const level=state.difficulty[state.current]==="challenge"?"challenge":"basic";
  const panel=document.createElement("div");panel.className="learning-feature-panel";panel.id="learningFeaturePanel";
  panel.innerHTML=`
   <section class="learning-feature-section">
    <div class="learning-feature-heading"><div><h2>Zwei Wege zum Üben</h2><p>Wähle, wie viel Unterstützung du für diese Aufgabe möchtest.</p></div><div class="difficulty-options" role="group" aria-label="Schwierigkeitsstufe"><button type="button" data-academy-difficulty="basic" aria-pressed="${level==="basic"}">Grundlage</button><button type="button" data-academy-difficulty="challenge" aria-pressed="${level==="challenge"}">Challenge</button></div></div>
    <div class="difficulty-content" ${level==="challenge"?"hidden":""}><h3>Grundlage</h3><p>${esc(lesson.task||"Bearbeite die Aufgabe aus dem Lektionstext.")}</p><p>Nutze das Beispiel als Starthilfe oder lade es direkt in den Editor.</p><pre class="feature-example">${esc(lesson.example||"Für diese Lektion ist kein Beispielcode hinterlegt.")}</pre><button class="feature-action" type="button" data-academy-load-example>Beispiel in den Editor laden</button></div>
    <div class="difficulty-content" ${level!=="challenge"?"hidden":""}><h3>Challenge</h3><p>${esc(lesson.taskChallenge||academyChallenge(lesson))}</p><p>Das Beispiel bleibt ausgeblendet. Nutze den Vergleich erst, wenn du deine Lösung selbst geprüft hast.</p></div>
   </section>
   <section class="learning-feature-section"><div class="learning-feature-heading"><div><h2>Vergleichsmodus</h2><p>Vergleiche die erwartete Ausgabe mit den console-Ausgaben deines letzten Laufs.</p></div><button class="feature-action" type="button" data-academy-toggle-comparison aria-expanded="${academyComparisonOn}">${academyComparisonOn?"Vergleich ausblenden":"Ausgabe vergleichen"}</button></div><div data-academy-comparison ${academyComparisonOn?"":"hidden"}>${academyComparisonMarkup(lesson)}</div></section>
   <section class="learning-feature-section"><h2>Fehler-Katalog</h2><p>Häufige Stolperstellen mit Symptom und konkretem Fix.</p><div class="error-catalog">${academyErrorCatalog.map(error=>`<details><summary>${esc(error.title)}</summary><p><strong>Symptom:</strong> ${esc(error.symptom)}</p><pre>${esc(error.sample)}</pre><p><strong>Fix:</strong> ${esc(error.fix)}</p></details>`).join("")}</div></section>
   ${academyReviewMarkup()}`;
  main.appendChild(panel);
  const actions=document.querySelector(".top-actions");
  if(actions){let badge=$("academyReviewBadge");if(!badge){badge=document.createElement("button");badge.id="academyReviewBadge";badge.className="small-btn";badge.type="button";badge.addEventListener("click",()=>$("learning-reviews")?.scrollIntoView({behavior:"smooth",block:"center"}));const theme=$("themeBtn");actions.insertBefore(badge,theme||null);}badge.textContent=`Wiederholen · ${academyDueReviews().length}`;badge.title="Zu fälligen Quiz-Wiederholungen springen";badge.setAttribute("aria-label",`${academyDueReviews().length} Quiz-Wiederholungen heute fällig`);}
  if(academyReviewingLesson===state.current){document.querySelectorAll("[data-answer]").forEach(button=>{button.disabled=false;button.classList.remove("correct","wrong");});const feedback=$("quizFeedback");if(feedback){feedback.textContent="Wiederholung: beantworte die Frage erneut.";feedback.style.color="";}}
 }

 const academyBaseRender=window.render;
 const academyBaseAnswerQuiz=window.answerQuiz;
 window.render=function(){academyBaseRender();academyRenderFeatures();};
 window.answerQuiz=function(answer){
  const index=state.current,lesson=lessons[index],isCorrect=answer===lesson.quiz.correct;
  academyBaseAnswerQuiz(answer);
  academyReviewingLesson=null;
  if(isCorrect){delete state.reviews[index];}
  else{const previous=state.reviews[index]?.interval||0;const interval=previous<1?1:previous<3?3:7;state.reviews[index]={interval,due:academyAddDays(interval)};}
  persist();academyRenderFeatures();
 };

 document.addEventListener("click",event=>{
  const levelButton=event.target.closest("[data-academy-difficulty]");
  if(levelButton){state.difficulty[state.current]=levelButton.dataset.academyDifficulty;persist();academyRenderFeatures();return;}
  if(event.target.closest("[data-academy-toggle-comparison]")){academyComparisonOn=!academyComparisonOn;academyRenderFeatures();return;}
  if(event.target.closest("[data-academy-load-example]")){
   const editor=$("codeInput");if(!editor)return;
   const example=lessons[state.current].example||"";
   if(editor.value.trim()&&editor.value!==example&&!confirm("Den aktuellen Editorinhalt durch das Beispiel ersetzen?"))return;
   if(typeof switchFile==="function"&&fileBuffers["main.js"]!==undefined)switchFile("main.js");
   editor.value=example;updateEditor();saveCurrentFile();editor.focus();return;
  }
  const reviewButton=event.target.closest("[data-academy-review]");
  if(reviewButton){academyReviewingLesson=Number(reviewButton.dataset.academyReview);go(academyReviewingLesson);return;}
  if(event.target.closest("#runCode")){
   state.lastOutput={lesson:state.current,lines:[]};persist();
   window.setTimeout(academyRenderFeatures,0);
  }
 });
 window.addEventListener("message",event=>{
  const data=event.data;if(!data||data.source!=="js-academy-preview")return;
  if(!state.lastOutput||state.lastOutput.lesson!==state.current)state.lastOutput={lesson:state.current,lines:[]};
  if(data.type==="log")state.lastOutput.lines.push((data.args||[]).join(" "));
  else if(data.type==="warn")state.lastOutput.lines.push("Warnung: "+(data.args||[]).join(" "));
  else if(data.type==="error")state.lastOutput.lines.push("Fehler: "+(data.args||[]).join(" "));
  persist();academyRenderFeatures();
 });
 window.render();
})();

;

document.documentElement.classList.add("academy-ready");

// Editor- und Lernkomfort: Tastaturbedienung sowie persönliche Notizen je Lektion.
(function () {
  if (!state.lessonNotes || typeof state.lessonNotes !== "object") state.lessonNotes = {};

  function renderLessonNotes() {
    const main = document.getElementById("lessonMain");
    if (!main) return;
    const previous = document.getElementById("lessonNotesPanel");
    if (previous) previous.remove();
    const index = state.current;
    const panel = document.createElement("section");
    panel.className = "learning-feature-section lesson-notes-panel";
    panel.id = "lessonNotesPanel";
    panel.innerHTML =
      '<div class="learning-feature-heading"><div><h2>Meine Notizen</h2><p>Halte eigene Erklärungen, Fragen oder Merksätze zu dieser Lektion fest. Deine Notizen werden automatisch in diesem Browser gespeichert.</p></div><span class="notes-save-status" id="lessonNotesStatus" aria-live="polite">Lokal gespeichert</span></div>' +
      '<label class="lesson-notes-label" for="lessonNotesInput">Persönliche Notizen · ' + (index + 1) + '. Lektion</label>' +
      '<textarea id="lessonNotesInput" class="lesson-notes-input" rows="5" placeholder="Was hast du gelernt? Was möchtest du noch üben?">' +
      String(state.lessonNotes[index] || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;") +
      '</textarea><div class="lesson-notes-actions"><button type="button" class="feature-action" id="downloadLessonNotes">Notizen herunterladen</button><button type="button" class="feature-action notes-clear" id="clearLessonNotes">Notizen dieser Lektion löschen</button></div>';
    main.appendChild(panel);
  }

  const previousRender = window.render;
  if (typeof previousRender === "function") {
    window.render = function () {
      previousRender();
      renderLessonNotes();
    };
  }

  document.addEventListener("input", function (event) {
    if (event.target && event.target.id === "lessonNotesInput") {
      state.lessonNotes[state.current] = event.target.value;
      persist();
      const status = document.getElementById("lessonNotesStatus");
      if (status) status.textContent = "Gespeichert";
    }
  });

  document.addEventListener("click", function (event) {
    if (event.target.closest("#clearLessonNotes")) {
      state.lessonNotes[state.current] = "";
      persist();
      const input = document.getElementById("lessonNotesInput");
      if (input) input.value = "";
      const status = document.getElementById("lessonNotesStatus");
      if (status) status.textContent = "Notizen gelöscht";
    }
    if (event.target.closest("#downloadLessonNotes")) {
      const note = String(state.lessonNotes[state.current] || "");
      const title = lessons[state.current].short || "Lektion";
      const blob = new Blob(["Notizen: " + title + "\n\n" + note + "\n"], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "javascript-academy-notizen-" + (state.current + 1) + ".txt";
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    }
  });

  // Editor: Tab fügt Leerzeichen ein, Enter übernimmt Einrückung, Strg+Enter führt aus.
  document.addEventListener("keydown", function (event) {
    const editor = event.target;
    if (!editor || editor.id !== "codeInput") return;

    if (event.key === "Tab") {
      event.preventDefault();
      editor.setRangeText("  ", editor.selectionStart, editor.selectionEnd, "end");
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      if (typeof updateEditor === "function") updateEditor();
      return;
    }

    if (event.key === "Enter" && !event.shiftKey && !event.ctrlKey && !event.metaKey && !event.altKey) {
      const start = editor.selectionStart;
      const before = editor.value.slice(0, start);
      const currentLine = before.slice(before.lastIndexOf("\n") + 1);
      const indent = (currentLine.match(/^\s*/) || [""])[0];
      const extraIndent = /\{\s*$/.test(currentLine) ? "  " : "";
      event.preventDefault();
      editor.setRangeText("\n" + indent + extraIndent, editor.selectionStart, editor.selectionEnd, "end");
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      if (typeof updateEditor === "function") updateEditor();
      return;
    }

    if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      const runButton = document.getElementById("runCode");
      if (runButton) runButton.click();
    }
  });
  renderLessonNotes();
})();
